// Generated by scripts/sync-rule-pages.mjs from the How to fix it and When to ignore it sections
// of each rule page. Do not edit by hand: edit the page under rules/ and rerun the script.

export interface RuleGuidance {
  /** The page's How to fix it, as Markdown. */
  fix: string;
  /** The page's When to ignore it with the generated ignore line; absent for a live-model rule. */
  ignore?: string;
}

/** What the results page copies for an AI assistant, per rule id. Example stays on the page. */
export const RULE_GUIDANCE: Readonly<Record<string, RuleGuidance>> = {
  ACTION_WITHOUT_DESTINATION: {
    fix: "In Power BI Desktop, select the button, and on the Button tab of the Format button pane, expand Action. With Type set to the action you meant, pick the page under Destination, the target drillthrough page for a drillthrough action, or, for a bookmark action, the bookmark under Bookmarks. Shapes and images carry actions too; select the one the finding names. To test the button while you edit, hold Ctrl and select it. If the button should not take readers anywhere, turn Action off.",
    ignore:
      'A button kept for its tooltip. Microsoft places a button\'s Tooltip under Action, among the same settings as the destination, and does not say whether the tooltip still shows once Action is turned off, so a button made only to show a tooltip may need its action left on. Among Power BI Desktop\'s saved files, Microsoft\'s own FinOps report has page navigation buttons with an empty destination and a tooltip each. Before ignoring the finding on such a button, turn Action off in Power BI Desktop and hover over the button: if the tooltip still shows, leave the action off and the finding clears; if it does not, turn Action back on and ignore the finding on that button. Any other button whose action names no destination is unfinished, so pick its destination or turn the action off.\n\nTo ignore this rule on one visual, add `{ "name": "pbiplint.ignore", "value": "ACTION_WITHOUT_DESTINATION" }` to the `annotations` array of its visual.json. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"ACTION_WITHOUT_DESTINATION": "off"` under `rules` in `pbiplint.config.json`.',
  },
  ADD_DATA_CATEGORY_FOR_COLUMNS: {
    fix: "In Power BI Desktop, select the column in the Data pane, open Column tools, and pick the Data category. In the TMDL file, add the property under the column: `dataCategory: City`, `dataCategory: Country`, `dataCategory: Continent`, `dataCategory: Latitude`, or `dataCategory: Longitude`. The property is metadata only, so setting it changes nothing about what the refresh loads or how the column compresses.",
    ignore:
      'A column the name test catches that holds no geography is the case to look for first: Country Manager is a person, City Code is an internal code nobody plots, and giving either a data category would be wrong rather than merely unnecessary. A latitude and longitude pair that only ever feeds a distance calculation is in the same position, since nothing binds it to a map. Where the column really is a place name and a report shows it on a map, there is no reason to leave the category off.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = ADD_DATA_CATEGORY_FOR_COLUMNS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"ADD_DATA_CATEGORY_FOR_COLUMNS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  "AVOID_BI-DIRECTIONAL_RELATIONSHIPS_AGAINST_HIGH-CARDINALITY_COLUMNS": {
    fix: "Find the cardinality first. In Power BI Desktop's DAX query view, run a query such as `EVALUATE ROW(\"n\", DISTINCTCOUNT('Sales'[Order ID]))` for each column in a bi-directional relationship. Then set the relationship back to single direction in the model view, or remove `crossFilteringBehavior: bothDirections` from it in the TMDL file, and where one report needs the reverse filter, get it from a measure with CROSSFILTER or TREATAS. DAX Studio's VertiPaq Analyzer shows every column's cardinality at once, and if you already use Tabular Editor, the walkthrough under Links loads the same statistics into its Best Practice Analyzer, which can then run this rule directly.",
  },
  AVOID_DUPLICATE_MEASURES: {
    fix: "Decide which name stays, repoint the visuals that use the other one, and delete it. In Power BI Desktop, right-click the measure in the Data pane and choose Delete from model. In the TMDL file, remove its `measure` block from the table.\n\nWhere published reports still bind to the second name, the interim step is to make it a plain reference to the survivor:\n\n```\nSales Amount = [Total Sales]\n```\n\nThat leaves one definition, so this rule stops reporting the pair, and it moves the finding to `MEASURES_SHOULD_NOT_BE_DIRECT_REFERENCES_OF_OTHER_MEASURES` until the reports are moved and the alias goes.",
    ignore:
      'Two measures that are identical only by accident of timing are worth keeping apart: Freight Cost and Handling Cost both reading the same column because the split in the source has not landed yet will diverge the week it does, and merging them now only means writing one of them again. Check whether the two names mean different things to the business before you delete either. Where they mean the same thing, there is nothing to weigh.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = AVOID_DUPLICATE_MEASURES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"AVOID_DUPLICATE_MEASURES": "off"` under `rules` in `pbiplint.config.json`.',
  },
  "AVOID_EXCESSIVE_BI-DIRECTIONAL_OR_MANY-TO-MANY_RELATIONSHIPS": {
    fix: "Take the direction off the relationships that do not need it. In Power BI Desktop, open the model view, double-click a relationship, and set Cross filter direction to Single in the Edit relationship dialog; in the TMDL file the same change is the `crossFilteringBehavior: bothDirections` line, deleted, since single direction is the default. Where one report genuinely needs the reverse filter, leave the relationship single and ask for the filter inside the measure that needs it, as in `Products Sold = CALCULATE(DISTINCTCOUNT('Product'[Product ID]), CROSSFILTER('Sales'[Product ID], 'Product'[Product ID], BOTH))`, so the cost falls on one visual instead of every query. For a many-to-many relationship, load a bridge table holding the distinct key values and relate both tables to it, which makes each hop many-to-one: in the dialog that is the Cardinality dropdown, and in the file it is `fromCardinality` and `toCardinality` on each relationship. The dialog and the properties read the same on an import model and a DirectQuery one.",
    ignore:
      'A small model is the usual false alarm. Three relationships with one deliberate bi-directional relationship among them is 33 percent and fires, and there is nothing excessive about one. Count the relationships before you read the finding as a verdict: the rule is a ratio, and a ratio over four relationships says almost nothing. A model built on a bridge table by design is the other case, for example one that maps accounts to account groups or budgets to regions, where the many-to-many relationships are the architecture rather than an accident. What is not a legitimate exception is a large model whose bi-directional relationships nobody can account for one by one; that is the finding doing its job.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = AVOID_EXCESSIVE_BI-DIRECTIONAL_OR_MANY-TO-MANY_RELATIONSHIPS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"AVOID_EXCESSIVE_BI-DIRECTIONAL_OR_MANY-TO-MANY_RELATIONSHIPS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  AVOID_FLOATING_POINT_DATA_TYPES: {
    fix: "Change the type where the data is loaded. In Power BI Desktop, choose Transform data, select the column, and pick Fixed decimal number or Whole number from Data Type on the Transform tab; on an import table that converts the values before they reach the model, and on a DirectQuery table the step folds into the query the source runs. You can also set the type in Table view or Report view: select the column, then pick the type from Data type on the Column tools tab. In the TMDL file the property is `dataType: decimal` for Fixed Decimal Number and `dataType: int64` for Whole Number. For a calculated column the type follows the expression, so convert it there: `Unit Price = CURRENCY(DIVIDE('Sales'[Amount], 'Sales'[Quantity]))` returns a fixed decimal whatever the division produced on its own. Best of all, fix the type in the view or the table the query reads, so every model that loads the column starts right.",
    ignore:
      'A value that genuinely needs more than four decimal places has to stay Double, and the rule has no way to know which those are. Latitude and longitude are the everyday case: four decimal places is about eleven metres, which is fine for a country map and wrong for a site plan, so a geography column is usually left alone. Scientific readings, unit conversion factors, and exchange rates quoted to six places are the same. Values above the Fixed Decimal Number range are the other case, since it tops out at about 922 trillion. Money is never the exception: if the column holds an amount someone will add up and reconcile, the rounding errors the rule warns about are exactly the ones that end up in a support ticket.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = AVOID_FLOATING_POINT_DATA_TYPES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"AVOID_FLOATING_POINT_DATA_TYPES": "off"` under `rules` in `pbiplint.config.json`.',
  },
  AVOID_INVALID_DESCRIPTION_CHARACTERS: {
    fix: "In Power BI Desktop, select the object in the Data pane or in model view and retype Description in the Properties pane, rather than editing around the character you cannot see. In the TMDL file the description is the run of `///` lines directly above the declaration, so retype those lines; an editor that shows control characters, or a search by code point, finds where the character is. Descriptions usually arrive pasted from a data dictionary, a ticket, or a spreadsheet cell, so if the same text is about to be pasted onto twenty more objects, clean it at the source first.",
    ignore:
      'There is no case for it. A control character in a description tells a reader nothing, and it stops the model from deploying at all.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = AVOID_INVALID_DESCRIPTION_CHARACTERS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"AVOID_INVALID_DESCRIPTION_CHARACTERS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  AVOID_INVALID_NAME_CHARACTERS: {
    fix: "In Power BI Desktop, double-click the field in the Data pane and retype the whole name rather than trying to select the character, or select the object and retype Name in the Properties pane. In the TMDL file the name is on the declaration line between single quotes, so `column 'Order ID'` is what the line should read once the character is gone; an editor that shows control characters, or a search by code point, finds where it was. Renaming in Desktop updates the visuals bound to the field; a hand edit in the TMDL file does not, so open the report and check its visuals after one. Where the character arrives with a source column name, rename the column in Power Query as well, so the next column you add from that query comes in clean.",
    ignore:
      'There is no case for it. The character shows a reader nothing, nobody can type it to reach the object, and it stops the model from deploying at all.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = AVOID_INVALID_NAME_CHARACTERS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"AVOID_INVALID_NAME_CHARACTERS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  AVOID_SHOW_ITEMS_WITH_NO_DATA: {
    fix: "In Power BI Desktop, select the visual, open the Build visual tab of the Visualizations pane, and in the well that holds the field select the arrow beside the field (or right-click it) and clear Show items with no data. Desktop sets the option for every field in the same well at once, so clearing it once clears the well.",
    ignore:
      'Some visuals exist to show gaps: a column chart of sales by month in which a month without sales has to appear as an empty column instead of vanishing from the axis, or a list of stores in which a store with no sales is itself what the reader is looking for. Keep the option on for those, grouped by a column from a small table, and ignore the finding on that visual.\n\nTo ignore this rule on one visual, add `{ "name": "pbiplint.ignore", "value": "AVOID_SHOW_ITEMS_WITH_NO_DATA" }` to the `annotations` array of its visual.json. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"AVOID_SHOW_ITEMS_WITH_NO_DATA": "off"` under `rules` in `pbiplint.config.json`.',
  },
  AVOID_STRUCTURED_DATA_SOURCES_WITH_PROVIDER_PARTITIONS: {
    fix: "Rewrite the partition as Power Query, which is what Power BI Desktop writes. In Desktop, choose Transform data, build the query against the source, and load it; Desktop writes an `m` partition every time and has no way to write a provider one. In the TMDL file, change `partition Sales = query` to `partition Sales = m`, replace the `source` block and its `query` and `dataSource` lines with a `source =` block holding the M expression, and delete the `dataSource` declaration from the file that holds it once no partition names it.\n\nThe other route keeps the provider partition and changes the data source instead, so both halves are legacy: replace the structured declaration with one that reads `dataSource 'Sales SQL' = provider` and carries a `connectionString`. The walkthrough in the links does that conversion with Tabular Editor.",
    ignore:
      'There is no case for keeping the pairing. Power BI rejects it, so the finding is the deployment failure arriving before the deployment. What is worth deciding first is which half to change: if the rest of the model\'s partitions are Power Query, the provider partition is the leftover and rewriting it is the smaller change; if the model came over from Analysis Services and every partition is a provider one, converting the single data source touches one object instead of many.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = AVOID_STRUCTURED_DATA_SOURCES_WITH_PROVIDER_PARTITIONS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"AVOID_STRUCTURED_DATA_SOURCES_WITH_PROVIDER_PARTITIONS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  AVOID_THE_USERELATIONSHIP_FUNCTION_AND_RLS_AGAINST_THE_SAME_TABLE: {
    fix: "Give the second relationship a table of its own, so no measure needs USERELATIONSHIP. In Power BI Desktop, choose Transform data, right-click the dimension's query, choose Reference, name the copy for the part it plays, Ship To Customer beside Customer, and load it. In model view, drag the fact table's second key onto the copy's key, which creates an active relationship, and delete the inactive one. Edit the measure in the formula bar so it is the plain aggregation again, and give the copy the same filter the original has, under Modeling, Manage roles. In the TMDL file that is a new `table` block with its own `ref table` line in `model.tmdl`, a `relationship` block with no `isActive: false` line, the expression after `measure 'Shipped Amount' =`, and a second `tablePermission` under the role.\n\nThe other route leaves the relationships alone and moves the row-level security instead: put the filter on a table that no measure re-points, and the pairing is gone. Work out what that changes for the reader before you do it, because filtering a dimension and filtering the fact table are not the same restriction.",
    ignore:
      'A role nobody is assigned to still counts. The rule pairs any role\'s filter with any measure, so on a Power BI semantic model, where membership lives in the service and never in the files, an abandoned role produces the finding although no reader ever meets the error. Check the workspace\'s security settings for the role before you restructure anything. Where the role is real and the measure is one a reader will use, the finding is the error they will see, and there is nothing here to ignore.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = AVOID_THE_USERELATIONSHIP_FUNCTION_AND_RLS_AGAINST_THE_SAME_TABLE` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"AVOID_THE_USERELATIONSHIP_FUNCTION_AND_RLS_AGAINST_THE_SAME_TABLE": "off"` under `rules` in `pbiplint.config.json`.',
  },
  "AVOID_USING_'1-(X/Y)'_SYNTAX": {
    fix: "Rewrite `1 - x / y` as `DIVIDE(y - x, y)`, and hold the shared denominator in a variable when it is used twice:\n\n```\nMargin % =\nVAR TotalAmount = SUM ( Sales[Amount] )\nRETURN DIVIDE ( TotalAmount - SUM ( Sales[Cost] ), TotalAmount )\n```\n\nIn Power BI Desktop, select the measure and edit it in the formula bar. In the TMDL file, edit the expression after `measure 'Margin %' =`.",
    ignore:
      "There is no case where the original shape is the better one. If a visual relies on the measure showing 100 percent where there is no data, that is a display decision, and it belongs in a measure that returns the value on purpose, not in a subtraction that happens to produce it.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = AVOID_USING_'1-(X/Y)'_SYNTAX` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"AVOID_USING_'1-(X/Y)'_SYNTAX\": \"off\"` under `rules` in `pbiplint.config.json`.",
  },
  "AVOID_USING_MANY-TO-MANY_RELATIONSHIPS_ON_TABLES_USED_FOR_DYNAMIC_ROW_LEVEL_SECURITY": {
    fix: "Give the two tables a dimension to meet on, so every hop is many-to-one. Load a small table of the distinct key values, one row per region in the example above, and in Power BI Desktop's model view drag both the security table's key and the fact or dimension key onto it; each new relationship is many-to-one because the new table's key is unique. In the TMDL file that is `fromCardinality: many` with `toCardinality: one`, which is what a relationship block with neither line already means, and marking the new table's key column with `isKey`. The security filter itself does not move: it stays where Modeling, Manage roles wrote it, as a `tablePermission` line under the role. Leave one bi-directional hop, from the security table up to the shared dimension, so the filter still reaches the facts, and make it that one hop rather than a many-to-many expansion. The patterns under Links set out the variants in full.",
    ignore:
      'The filter is the thing to look at first. This rule counts any row-level security filter, so a table filtered by a static expression such as `[Region] = "East"` is reported exactly like one filtered by a lookup on the signed-in user. A static filter resolves to the same rows for everyone in the role, so the expansion is cached and shared instead of repeated per user. The direction of the relationship is the second check: the finding only asks whether a many-to-many relationship touches the table, not whether the security filter travels through it, so a many-to-many relationship pointing away from the secured path costs nothing here. Size is the third: a security table of a few hundred rows expands cheaply, and the trade the rule assumes is one worth measuring in the service with the role applied before you rebuild anything. A large secured table reached through more than one many-to-many hop is the case the rule was written for, and there ignoring it is not defensible.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = AVOID_USING_MANY-TO-MANY_RELATIONSHIPS_ON_TABLES_USED_FOR_DYNAMIC_ROW_LEVEL_SECURITY` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"AVOID_USING_MANY-TO-MANY_RELATIONSHIPS_ON_TABLES_USED_FOR_DYNAMIC_ROW_LEVEL_SECURITY": "off"` under `rules` in `pbiplint.config.json`.',
  },
  AVOID_USING_THE_IFERROR_FUNCTION: {
    fix: "Where IFERROR guards a division, DIVIDE does the same job with the same fallback, and its third argument is what IFERROR was returning:\n\n```\nAverage Price = DIVIDE ( SUM ( Sales[Amount] ), SUM ( Sales[Quantity] ), 0 )\n```\n\nIn Power BI Desktop, select the measure in the Data pane and edit it in the formula bar; a calculated column is edited the same way with the column selected. In the TMDL file, edit the expression after `measure 'Average Price' =`, or after `column Name =` for a calculated column. Where the call is guarding a type conversion rather than a division, change the column's type in Power Query so the conversion cannot fail, and drop the guard. Where a guard is genuinely needed, test the condition with IF, which leaves the engine free to evaluate in bulk.",
    ignore:
      'A calculated column on an imported table is materialized once per refresh and never again at query time, so the cost of the guard is paid by the refresh, not by every visual. IFERROR in a calculated column over a small table is a fair trade while the underlying data problem is being sorted out upstream. A measure is the opposite case: it runs on every query, so the guard is worth removing even when the model is small today.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = AVOID_USING_THE_IFERROR_FUNCTION` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"AVOID_USING_THE_IFERROR_FUNCTION": "off"` under `rules` in `pbiplint.config.json`.',
  },
  BROKEN_ACTION_TARGET: {
    fix: "In Power BI Desktop, select the button, and on the Button tab of the Format button pane, expand Action. Check that Type is the action you meant, then pick the page under Destination, the target drillthrough page for a drillthrough action, or, for a bookmark action, the bookmark under Bookmarks. Shapes and images carry actions too; select the one the finding names. To test the button while you edit, hold Ctrl and select it. If the button should not do anything any more, turn Action off or delete the button.",
    ignore:
      'There is no legitimate case. An action whose destination is not in the report has nowhere in it to take readers, so point it at a page or bookmark that exists, or turn the action off if the button is meant to do nothing.\n\nTo ignore this rule on one visual, add `{ "name": "pbiplint.ignore", "value": "BROKEN_ACTION_TARGET" }` to the `annotations` array of its visual.json. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"BROKEN_ACTION_TARGET": "off"` under `rules` in `pbiplint.config.json`.',
  },
  BROKEN_BOOKMARK_REFERENCE: {
    fix: "In Power BI Desktop, on the View tab, select Bookmarks to open the Bookmarks pane. Go to the page the bookmark should show, arrange its visuals as the bookmark should leave them, then select More options (...) next to the bookmark's name and choose Update. If nobody needs the bookmark any more, choose Delete from the same menu. Deleting it and adding a new one from the right page also works, but a button keeps pointing at the bookmark it was set to, not at its display name, so point any button that used the old one at the new one; `BROKEN_ACTION_TARGET` reports any that still name it. For a captured visual that is no longer on the page, opening the report in Desktop and saving it is enough, since Desktop removes such visuals from the bookmark when it saves. For a target visual, saving is not enough: select the visuals the bookmark should apply to, on the page or in the Selection pane (hold Ctrl to select more than one), then choose Update from the bookmark's More options (...) menu.",
    ignore:
      'There is no legitimate case. A bookmark that names a page or visual the report lacks keeps state for, or applies to, something that is not there, so recapture it or delete it; a bookmark nobody uses is better deleted than ignored.\n\nThis rule reports on bookmarks, and a bookmark\'s file has no place for an annotation, so there is no object to annotate. To turn the rule off for a whole project, set `"BROKEN_BOOKMARK_REFERENCE": "off"` under `rules` in `pbiplint.config.json`.',
  },
  BROKEN_FIELD_REFERENCE: {
    fix: "In Power BI Desktop, select the visual the finding names, remove the broken field from its well in the Visualizations pane, and add the field you meant from the Data pane. Other kinds of reference have their own routes:\n\n- For conditional formatting, open the formatting option's fx dialog and pick a valid field, or remove the formatting and apply it again with the right field.\n- For a filter, remove the broken card from the Filters pane and add the field again.\n- For a bookmark, fix the page it shows first. Then select the bookmark and choose Update from its More options menu, so it captures the page again.\n- For a text box's field value, delete the text box and add it again with the field you meant.\n- When the model is what changed, put the field back in the model under the name the report uses. If the field was renamed, renaming it back fixes every reference to it at once.",
    ignore:
      'There is no legitimate exception, because a reference the model cannot resolve is broken for every reader of the report.\n\nTo ignore this rule on one page or visual, add `{ "name": "pbiplint.ignore", "value": "BROKEN_FIELD_REFERENCE" }` to the `annotations` array of its page.json or visual.json. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"BROKEN_FIELD_REFERENCE": "off"` under `rules` in `pbiplint.config.json`.',
  },
  CALCULATION_GROUPS_WITH_NO_CALCULATION_ITEMS: {
    fix: "In Power BI Desktop, open Model view, find the group under Calculation groups in the Model explorer pane, choose New calculation item, and write its DAX in the formula bar. In the TMDL file the group is a `calculationGroup` block under the table, and each item is a `calculationItem` inside it with its DAX after the `=`. If the group is not wanted, delete the table: in Desktop, right-click it in the Data pane and choose Delete from model; in the project, remove its file from the `tables` folder and its `ref table` line from `model.tmdl`.",
    ignore:
      'The one moment the finding is noise is while you are building the group, between creating it and writing the first item, when it tells you something you already know. There is no reason to ship one: an empty group is a field in the list that does nothing when a report author uses it.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = CALCULATION_GROUPS_WITH_NO_CALCULATION_ITEMS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"CALCULATION_GROUPS_WITH_NO_CALCULATION_ITEMS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  "CHECK_IF_BI-DIRECTIONAL_AND_MANY-TO-MANY_RELATIONSHIPS_ARE_VALID": {
    fix: "Look at each one and decide whether it was meant. In Power BI Desktop, open the model view, double-click the relationship, and read the Cardinality and Cross filter direction dropdowns in the Edit relationship dialog; in the TMDL file the same three facts are `fromCardinality`, `toCardinality`, and `crossFilteringBehavior` under the relationship. Where the direction is not wanted, set Cross filter direction to Single, which is the `crossFilteringBehavior: bothDirections` line deleted, and move the reverse filter into the measures that need it with CROSSFILTER. Where the cardinality is many-to-many because the key column has duplicates, that is a data problem: remove the duplicates in Power Query with Remove Duplicates, or in the source view the query reads, then set Cardinality back to Many to one. Both dropdowns behave the same on an import model and a DirectQuery one.",
    ignore:
      'Ignoring is the ordinary outcome for a relationship you meant to create, and this rule exists to make you say so once. A bridge table between two dimensions, a security table that has to filter upward, a slicer that has to narrow to the values a fact table actually holds: each is a deliberate design and each stays. The check worth making before you ignore one is for a second filter path between the same two tables, which the model view shows as two routes; one route is a design, two is where the totals start disagreeing. Review the list again whenever relationships are added, because a path that was unique when you approved it may not be now.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = CHECK_IF_BI-DIRECTIONAL_AND_MANY-TO-MANY_RELATIONSHIPS_ARE_VALID` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"CHECK_IF_BI-DIRECTIONAL_AND_MANY-TO-MANY_RELATIONSHIPS_ARE_VALID": "off"` under `rules` in `pbiplint.config.json`.',
  },
  "CHECK_IF_DYNAMIC_ROW_LEVEL_SECURITY_(RLS)_IS_NECESSARY": {
    fix: 'Decide whether the mapping has to be dynamic, then act on the decision. Keep the dynamic filter where the user-to-rows mapping lives in a table that changes without a redeploy, or where there are more audiences than anyone would maintain by hand. Otherwise replace it: in Power BI Desktop, under Modeling, Manage roles, create one role per audience with a plain filter such as `[Region] = "East"`, then delete the dynamic role in the same dialog. In the TMDL file each role is a `role` block in the roles folder, and each filter is the expression after the `=` on a `tablePermission` line under it, so a static filter is the same line with the USERPRINCIPALNAME call gone. Members are assigned after publishing, in the workspace under Security on the semantic model; Power BI Desktop writes roles but never members. Where the dynamic filter stays, the thing worth shortening is the lookup behind it: hold the user-to-key mapping in a small table with the key already computed, so the filter is one comparison instead of a search.',
    ignore:
      'Dynamic row-level security is a design, not a defect, and this rule is a prompt to confirm the design once rather than a queue to clear. Ignore it wherever the mapping table is the point: a model whose audience is every salesperson in the company, a hierarchy where a manager sees their reports\' rows, anything where a new user should get access by appearing in a table rather than by someone editing the model. The finding is worth a second look in two places. One is a model with two or three fixed audiences, where static roles are simpler to explain to whoever audits access. The other is a dynamic filter over a large secured table, where the per-user lookup runs on every query and the fix is to precompute the key rather than to drop the pattern.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = CHECK_IF_DYNAMIC_ROW_LEVEL_SECURITY_(RLS)_IS_NECESSARY` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"CHECK_IF_DYNAMIC_ROW_LEVEL_SECURITY_(RLS)_IS_NECESSARY": "off"` under `rules` in `pbiplint.config.json`.',
  },
  DATA_COLUMNS_MUST_HAVE_A_SOURCE_COLUMN: {
    fix: "Power BI Desktop writes `sourceColumn` whenever it adds a column to a table, so a finding here means the column was written or edited by hand, or arrived in a migration. In the TMDL file, add a `sourceColumn:` line under the column, naming the field the partition's query produces and spelling it the way the query spells it. Where the query no longer produces it, the fix runs the other way: add the column back in Power Query, under Transform data, so the next refresh delivers it, or take the column out of the model, in Desktop by right-clicking it in the Data pane and choosing Delete from model, or by removing its `column` block from the table's TMDL file.",
    ignore:
      'There is none. A data column with no source column stops the whole table from loading, so the finding is a refresh failure reported before the refresh. The one thing worth checking is whether the column was meant to be a calculated column: if it was, give it a DAX expression instead, and the column leaves this rule for `EXPRESSION_RELIANT_OBJECTS_MUST_HAVE_AN_EXPRESSION`, which asks the same question of the expression.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = DATA_COLUMNS_MUST_HAVE_A_SOURCE_COLUMN` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"DATA_COLUMNS_MUST_HAVE_A_SOURCE_COLUMN": "off"` under `rules` in `pbiplint.config.json`.',
  },
  "DATE/CALENDAR_TABLES_SHOULD_BE_MARKED_AS_A_DATE_TABLE": {
    fix: "In Power BI Desktop, select the table in the Data pane, open Table tools, choose Mark as date table, and pick the column that holds the dates. Desktop checks the column before it accepts it: the values must be unique, have no blanks, carry the same time of day throughout, and run without a gap from the first day to the last. In the TMDL file the result is `dataCategory: Time` on the table and `isKey` on that column, and both have to be present before the finding clears. Where the column fails the check, fix it where it is loaded: in Transform data, remove the time part with Date under the Transform tab, drop the duplicate rows, and fill the gaps by generating the date table rather than deriving it from a fact table. Where the model uses calendar-based time intelligence, a preview in Power BI Desktop, defining a calendar on the table under Calendar options in Table tools clears the finding instead, since its functions need the marking only in the cases Microsoft lists ([When you must mark your date table](https://learn.microsoft.com/power-bi/transform-model/desktop-date-tables#when-you-must-mark-your-date-table)). Calendar options appears only once the Enhanced DAX Time Intelligence preview is turned on, under File, Options and settings, Options, Preview features ([Enable the enhanced DAX Time Intelligence preview](https://learn.microsoft.com/power-bi/transform-model/desktop-time-intelligence#enable-the-enhanced-dax-time-intelligence-preview)). Where the table is not a date table at all and only the name caught it, rename it or ignore the finding on it.",
    ignore:
      'The name test is a plain substring, so Updates, Candidates, and Mandates are all reported with no date in them anywhere. Those findings are noise and the rule has no way to see it. A table that holds dates without being a date table is the more interesting case: an Event Calendar of scheduled events, or a Date Changes audit log. Marking either one would be wrong, because it is a fact table and the marking declares a calendar key. A date table at a grain other than the day is the third case, for example a Fiscal Calendar of one row per period; Mark as date table requires one contiguous row per day, so the table cannot be marked; a calendar defined on it, which needs no row for every day, clears the finding, and without one the finding stays for as long as the table exists. What is not a legitimate exception is the model\'s real day-grain date table left unmarked where Microsoft asks for the marking: when the model uses the classic time intelligence functions, relates the date table to other tables on a column that is not a date, or is read with advanced date filters in Excel PivotTables ([When you must mark your date table](https://learn.microsoft.com/power-bi/transform-model/desktop-date-tables#when-you-must-mark-your-date-table)).\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = DATE/CALENDAR_TABLES_SHOULD_BE_MARKED_AS_A_DATE_TABLE` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"DATE/CALENDAR_TABLES_SHOULD_BE_MARKED_AS_A_DATE_TABLE": "off"` under `rules` in `pbiplint.config.json`.',
  },
  DATECOLUMN_FORMATSTRING: {
    fix: "In Power BI Desktop, select the column in the Data pane and set Format under Column tools. In the TMDL file, add `formatString: mm/dd/yyyy` under the column. The format string changes only how the value is rendered; the stored value and the data type are untouched, so nothing downstream of the model has to change with it.",
    ignore:
      'A model whose house convention is a different date order has nothing to gain here: every date column in it fires, and rewriting them all to the US short date is a worse outcome than the finding. Pick the format your readers expect, set it consistently, and treat the rule as house style you have already settled. The other case is a DateTime column that is not a date a reader ever sees, such as a hidden load timestamp caught by the name test, where a format string changes nothing on screen.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = DATECOLUMN_FORMATSTRING` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"DATECOLUMN_FORMATSTRING": "off"` under `rules` in `pbiplint.config.json`.',
  },
  DAX_COLUMNS_FULLY_QUALIFIED: {
    fix: "Put the table name in front of every column reference:\n\n```\nTotal Sales = SUM ( 'Sales'[Amount] )\n```\n\nIn Power BI Desktop, select the measure in the Data pane and edit it in the formula bar, which completes the qualified form as soon as you start typing the table name. A row-level security filter is edited under Modeling, Manage roles. In the TMDL file, edit the expression after `measure 'Total Sales' =`, or the filter after `tablePermission Sales =` inside the role. A finding that only the measure's KPI raises is fixed in the TMDL file, after `targetExpression =`, `statusExpression =`, or `trendExpression =` in the measure's `kpi` block, an edit Power BI Desktop keeps.",
    ignore:
      'There is no case for the bare form. The rule is worth reading as a warning rather than a style note: the reference that fires it resolved to a column because no measure of that name exists today, and the day someone adds one, the expression silently starts reading the measure instead. Qualifying it is what stops that.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = DAX_COLUMNS_FULLY_QUALIFIED` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"DAX_COLUMNS_FULLY_QUALIFIED": "off"` under `rules` in `pbiplint.config.json`.',
  },
  DAX_MEASURES_UNQUALIFIED: {
    fix: "Delete the table name from the reference and leave the brackets:\n\n```\nAverage Price = DIVIDE ( [Total Sales], SUM ( Sales[Quantity] ) )\n```\n\nIn Power BI Desktop, select the measure in the Data pane and edit it in the formula bar; the same goes for a calculated column, a calculated table, and a calculation item, each selected in the model view or the Data pane. In the TMDL file, edit the expression after `measure 'Average Price' =`, after `column Name =` for a calculated column, after `source =` in a calculated table's partition, or after `calculationItem Name =` in the calculation group. A finding that only the measure's KPI raises is fixed in the TMDL file, after `targetExpression =`, `statusExpression =`, or `trendExpression =` in the measure's `kpi` block, an edit Power BI Desktop keeps.",
    ignore:
      'There is no case for the table prefix on a measure. If a finding surprises you, check whether the table really does hold a measure of that name: pbiplint resolves `\'Table\'[Name]` to a column first and only calls it a measure when the table has no column of that name, so a finding here means the reference bound to a measure.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = DAX_MEASURES_UNQUALIFIED` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"DAX_MEASURES_UNQUALIFIED": "off"` under `rules` in `pbiplint.config.json`.',
  },
  DECIMAL_COLUMN_WITHOUT_FORMAT_STRING: {
    fix: "In Power BI Desktop, select the column in the Data pane and set Format under Column tools, or select it in Model view and set Format in the Properties pane ([Add a model level format string](https://learn.microsoft.com/power-bi/create-reports/desktop-custom-format-strings#add-a-model-level-format-string)). In the column's TMDL file, add a `formatString:` line under the column, such as `formatString: 0.0%` for a ratio or `formatString: #,0.00` for an amount.",
    ignore:
      'When no reader sees the column as a number: a decimal kept for a relationship or read only by measures is better hidden than formatted, which clears the finding too. Coordinates are the other case: a latitude or longitude column is there to place points on a map, not to be read as a number, so leaving it at General is fine. Otherwise a visible decimal column is one a report author can drop into a visual, where it shows with no format of its own.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = DECIMAL_COLUMN_WITHOUT_FORMAT_STRING` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"DECIMAL_COLUMN_WITHOUT_FORMAT_STRING": "off"` under `rules` in `pbiplint.config.json`.',
  },
  DEFAULT_PAGE_NAME: {
    fix: "In Power BI Desktop, right-click the page's tab at the bottom of the report, select Rename Page, and type the new name. Or, with nothing selected on the page, select the Page information card in the Format pane and type the name into Name.\n\nA page navigator's buttons take the new name on their own. A button that picks its destination from a table of page names, through conditional formatting, does not: Power BI matches those values to the page names exactly, so change the name in that table too.",
    ignore:
      'A page whose real name has one of these shapes is named on purpose. A report that reproduces a printed document page for page, with pages called `Page 1` and `Page 2` to match the original, is the usual case; ignore the finding on those pages.\n\nTo ignore this rule on one page, add `{ "name": "pbiplint.ignore", "value": "DEFAULT_PAGE_NAME" }` to the `annotations` array of its page.json. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"DEFAULT_PAGE_NAME": "off"` under `rules` in `pbiplint.config.json`.',
  },
  ENSURE_ALTTEXT: {
    fix: "In Power BI Desktop, select the visual, open the Format pane, expand General, and fill in Alt text at the bottom of the card; it takes up to 250 characters. Describe what a reader should take away rather than how the visual looks, since the screen reader already announces the title and type. For a figure that changes with the filters, the fx button beside Alt text binds it to a measure that writes the sentence. For a visual group, select the group itself: a first click on a visual inside a group selects the group, or select the group by name in the Selection pane. Then fill in Alt text under General in the Format pane.",
    ignore:
      'A purely decorative element, such as a background image, carries nothing for a screen reader to say. Take it out of the tab order in the Selection pane so screen readers skip it, and ignore the finding on it.\n\nTo ignore this rule on one visual, add `{ "name": "pbiplint.ignore", "value": "ENSURE_ALTTEXT" }` to the `annotations` array of its visual.json. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"ENSURE_ALTTEXT": "off"` under `rules` in `pbiplint.config.json`.',
  },
  ENSURE_PAGES_DO_NOT_SCROLL_VERTICALLY: {
    fix: "Split the page: move the lower half to a page of its own, or to a drillthrough page if it holds detail about one item. Where the content has to stay together, tighten it, with fewer or smaller visuals, or with bookmarks that switch between two views in the same space. Then set the height back: in Power BI Desktop, click an empty part of the canvas so the Format pane shows the page, open Canvas settings, and choose the 16:9 type, or set the Height under the Custom type.",
    ignore:
      'A page designed to be scrolled, laid out as one long column for Fit to width and read that way, is a deliberate choice, and so is a page sized for printing. Before deciding, open the page the way readers do, in the Power BI service or on the device they use, and check that nothing important sits below the first screen.\n\nTo ignore this rule on one page, add `{ "name": "pbiplint.ignore", "value": "ENSURE_PAGES_DO_NOT_SCROLL_VERTICALLY" }` to the `annotations` array of its page.json. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"ENSURE_PAGES_DO_NOT_SCROLL_VERTICALLY": "off"` under `rules` in `pbiplint.config.json`.',
  },
  ENSURE_TABLES_HAVE_RELATIONSHIPS: {
    fix: "In Power BI Desktop, open Model view and drag the key column of the fact table onto the matching column of the dimension, or use Manage relationships, New, and pick the two columns. Check the cardinality and the cross filter direction that Desktop proposes before you accept them. In the TMDL file a relationship is a `relationship` block of its own, with `fromColumn` on the many side and `toColumn` on the one side, each written as `Table.Column`. If the table really does stand alone, leave it as it is.",
    ignore:
      'A table that is meant to stand alone is the case to ignore: a what-if parameter table, a field parameter table, a table of slicer labels that a measure reads with SELECTEDVALUE, a list of thresholds compared against measures, or a lookup table read only by a row-level security filter. Check that the table is one of those before you ignore the finding, because the same line appears when a relationship was dropped in a merge or when a rename left the relationship pointing at a table name that no longer exists.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = ENSURE_TABLES_HAVE_RELATIONSHIPS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"ENSURE_TABLES_HAVE_RELATIONSHIPS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  ENSURE_THEME_COLOURS: {
    fix: "In Power BI Desktop, select the visual, open the Format pane, find the colour (for this chart's bars, Bars, then Color), and pick a swatch from Theme colors at the top of the colour picker instead of More colors. To return a whole section of the Format pane to the theme, use Reset to default at the bottom of that section. If the report needs a colour its theme does not have, add it to the theme (View, then Themes, then Customize current theme) so that every visual can pick it from the palette.",
    ignore:
      'A colour that must not change with the theme is set by hand on purpose: a partner\'s brand colour on their own logo card, say, or party colours on an election map. Before ignoring the finding on those visuals, consider whether the colour belongs in the theme instead, where every visual can use it and a later rebrand can still reach it.\n\nTo ignore this rule on one visual, add `{ "name": "pbiplint.ignore", "value": "ENSURE_THEME_COLOURS" }` to the `annotations` array of its visual.json. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"ENSURE_THEME_COLOURS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  EVALUATEANDLOG_SHOULD_NOT_BE_USED_IN_PRODUCTION_MODELS: {
    fix: "Delete the wrapper and keep what was inside it. EVALUATEANDLOG returns its first argument unchanged, so removing it cannot change the result:\n\n```\nAverage Price = DIVIDE ( SUM ( Sales[Amount] ), SUM ( Sales[Quantity] ) )\n```\n\nIn Power BI Desktop, select the measure in the Data pane and edit it in the formula bar. In the TMDL file, edit the expression after `measure 'Average Price' =`. Where the call has a second argument it is only the label the trace event carries, so it goes with the wrapper.",
    ignore:
      'While you are actually debugging the measure, the call is the point, and the finding is telling you what you already know. The rule is worth leaving on so the call cannot reach a published model by accident: ignore the finding for the length of the investigation, not for the life of the measure. A model that is never published, such as a scratch file used to work out a pattern, is the one case where the finding has nothing behind it.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = EVALUATEANDLOG_SHOULD_NOT_BE_USED_IN_PRODUCTION_MODELS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"EVALUATEANDLOG_SHOULD_NOT_BE_USED_IN_PRODUCTION_MODELS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  EXPRESSION_RELIANT_OBJECTS_MUST_HAVE_AN_EXPRESSION: {
    fix: "Write the DAX, or delete the object. In Power BI Desktop, select the measure in the Data pane and type the expression in the formula bar, or right-click it and choose Delete from model; a calculated column takes the same two routes from the same pane, and a calculation item is edited in the calculation group's own view. In the TMDL file the expression is whatever follows the `=`, either on the declaration line or in the block indented beneath it, so `measure 'Total Margin' = SUM(Sales[Amount]) - SUM(Sales[Cost])` is the whole repair. Where the object is not wanted, remove its `measure`, `column`, or `calculationItem` block instead.",
    ignore:
      'There is no case for keeping one. An object with no expression returns nothing wherever a report puts it, and the deployment may refuse it outright. A measure left blank as a placeholder while the work is unfinished is the closest thing to an exception, and giving it a body of `BLANK()` costs nothing and keeps the model valid in the meantime.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = EXPRESSION_RELIANT_OBJECTS_MUST_HAVE_AN_EXPRESSION` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"EXPRESSION_RELIANT_OBJECTS_MUST_HAVE_AN_EXPRESSION": "off"` under `rules` in `pbiplint.config.json`.',
  },
  FILTER_COLUMN_VALUES: {
    fix: "Drop the FILTER and pass the predicate itself. Wrap it in KEEPFILTERS to keep whatever filter the visual already puts on the column, which is what the FILTER form was doing:\n\n```\nBike Sales = CALCULATE ( [Total Sales], KEEPFILTERS ( 'Product'[Category] = \"Bikes\" ) )\n```\n\nLeave KEEPFILTERS off to replace that filter instead, which is what a bare predicate inside CALCULATE means. The SQLBI article under Links covers which one you want. In Power BI Desktop, select the measure in the Data pane and edit it in the formula bar; a calculated column and a calculation item are edited the same way. In the TMDL file, edit the expression after `measure 'Bike Sales' =`, after `column Name =` for a calculated column, or after `calculationItem Name =` in the calculation group.",
    ignore:
      "A predicate that reads two columns of the same table row by row has no column equivalent: `FILTER('Sales', 'Sales'[Amount] > 'Sales'[Budget])` needs the row context that FILTER supplies, and there is nothing to rewrite. The finding is also worth less on a small dimension table, where the table has a few hundred rows and the column a few dozen distinct values, than on a fact table with millions. What to check before deciding is which table the FILTER is over, not which table the measure lives on.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = FILTER_COLUMN_VALUES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"FILTER_COLUMN_VALUES\": \"off\"` under `rules` in `pbiplint.config.json`.",
  },
  FILTER_MEASURE_VALUES_BY_COLUMNS: {
    fix: "Iterate the column the answer actually varies by, not the table:\n\n```\nBest Seller Sales = CALCULATE ( [Total Sales], FILTER ( VALUES ( 'Product'[Product ID] ), [Total Sales] > 1000 ) )\n```\n\nVALUES respects the filter already on the column; swap in ALL to ignore it. Pick the column with the fewest distinct values that still gives the right answer, and note that passing a column also narrows what the filter carries into CALCULATE, one column's values rather than whole rows of the table, so the rewrite pays even where the column you iterate is the table's key. In Power BI Desktop, select the measure in the Data pane and edit it in the formula bar; a calculated column and a calculation item are edited the same way. In the TMDL file, edit the expression after `measure 'Best Seller Sales' =`, after `column Name =` for a calculated column, or after `calculationItem Name =` in the calculation group.",
    ignore:
      'Where the measure\'s value depends on more than one column of the table, no single column\'s distinct values reproduce the row set, and iterating the table is the honest form. Sales per product and store is the usual shape: iterate both columns together rather than the table if you can, and leave the finding alone if you cannot. The finding is also worth less over a small dimension, where the table has a few hundred rows and the column a few dozen distinct values, than over a fact table.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = FILTER_MEASURE_VALUES_BY_COLUMNS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"FILTER_MEASURE_VALUES_BY_COLUMNS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  FILTERS_PANE_STATE: {
    fix: "In Power BI Desktop, collapse the Filters pane, or expand it for a policy of open, and save the report in that state. To keep the pane from readers altogether, select the eye icon next to Filters in the pane; that is a third state, which neither policy accepts.",
    ignore:
      'Only when the project has no single state its reports should open with, and then the right move is to set no policy, which leaves the rule silent, rather than to ignore findings one report at a time.\n\nThis rule reports on the report itself, so there is no object to annotate. To turn the rule off for a whole project, set `"FILTERS_PANE_STATE": "off"` under `rules` in `pbiplint.config.json`.',
  },
  FIRST_LETTER_OF_OBJECTS_MUST_BE_CAPITALIZED: {
    fix: "In Power BI Desktop, double-click the object in the Data pane and retype the name, or select it and edit Name in the Properties pane of the model view. In the TMDL file the name is on the declaration line, so `measure 'total sales' =` becomes `measure 'Total Sales' =`. Renaming in Desktop carries the new name into the visuals bound to the object and into the DAX that references it; a hand edit in the file does not, so open the report and check its visuals after one.",
    ignore:
      'A name that is lower case on purpose is the exception worth keeping: eCommerce Orders, iPhone Sales, and anything else whose spelling belongs to a brand rather than to your style guide. Capitalizing those makes them wrong rather than tidy. Outside that, a lower case first letter is a slip, and the rule is reporting it before a reader does.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = FIRST_LETTER_OF_OBJECTS_MUST_BE_CAPITALIZED` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"FIRST_LETTER_OF_OBJECTS_MUST_BE_CAPITALIZED": "off"` under `rules` in `pbiplint.config.json`.',
  },
  FIX_REFERENTIAL_INTEGRITY_VIOLATIONS: {
    fix: "Find the orphans first. In Power BI Desktop's DAX query view, run a query such as `EVALUATE EXCEPT(VALUES('Sales'[Product Key]), VALUES('Product'[Product Key]))` for each relationship you suspect, which lists the keys the dimension is missing. Then fix the data where it is loaded: add the missing rows to the dimension query, or add an Unknown row to the dimension and map the orphan keys to it in Power Query or in the warehouse view behind it. Where the orphans are legitimate and the dimension cannot grow, filter the fact rows out in Power Query instead, so the blank member never appears. DAX Studio's VertiPaq Analyzer reads the violation count for every relationship at once if you would rather start from a list than a query per relationship.",
  },
  "FORMAT_FLAG_COLUMNS_AS_YES/NO_VALUE_STRINGS": {
    fix: "The values have to change, not just the type, so the fix lives upstream of the model. In Power BI Desktop, choose Transform data, select the query, and either add a conditional column that returns Yes or No or use Replace Values on the column itself, then set the column's type to Text in Power Query. Where the query reads a view or a stored procedure, do the same in the select list and the model gets the text column already formed. The Data type box under Column tools changes the type in place on an import model but leaves the values as 0 and 1, so it is not the fix on its own. If a measure counts the flag, keep the numeric column and hide it, which also takes it out of this rule's reach.",
    ignore:
      'A column whose type is already boolean is the common false alarm: Power BI shows it as True and False, which reads as well as Yes and No, and the rule reports it only because it tests for text. The name tests catch words that are not flags at all, so a whole-number Issue Count or Isotope Number is noise on the Is side. The case worth acting on is the one the rule was written for: a visible 0 and 1 column that a report author has to decode.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = FORMAT_FLAG_COLUMNS_AS_YES/NO_VALUE_STRINGS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"FORMAT_FLAG_COLUMNS_AS_YES/NO_VALUE_STRINGS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  HARDCODED_PERIOD_IN_DAX: {
    fix: "Take the period from something that moves with time.\n\n- For the current period, use `TODAY()`: `YEAR(TODAY())` for this year, as the fixed example does, or `TODAY()` itself for an as-of date.\n- For the latest period in the data, which stays right when a refresh runs late, take it from the fact table: `YEAR(MAX(Sales[Order Date]))`. Inside a measure, MAX reads only the dates the visual's filters leave, so write `CALCULATE(MAX(Sales[Order Date]), REMOVEFILTERS())` when the measure needs the latest date in all the data.\n- When a report reader should choose the period, add a parameter: on the Modeling tab, select New parameter, then Numeric range, and set its Minimum and Maximum to the first and last years it should offer. Power BI Desktop creates the parameter and, with it, a measure that gives the parameter's current value ([what-if parameters](https://learn.microsoft.com/power-bi/transform-model/desktop-what-if#create-a-parameter)), and your measure compares with that measure instead of a number. Parameters are [designed for measures](https://learn.microsoft.com/power-bi/transform-model/desktop-what-if#considerations-and-limitations), so this route suits a measure, not a calculated column.\n\nA filter argument of CALCULATE written as a comparison, as in the example, [can't reference a measure or use a nested CALCULATE](https://learn.microsoft.com/dax/calculate-function-dax#boolean-filter-expressions), so put the latest year or the parameter's value in a variable first:\n\n```\nLatest Year Sales =\nVAR LatestYear = YEAR ( CALCULATE ( MAX ( Sales[Order Date] ), REMOVEFILTERS () ) )\nRETURN\n    CALCULATE ( SUM ( Sales[Amount] ), YEAR ( Sales[Order Date] ) = LatestYear )\n```\n\nFor a date table, end CALENDAR on the data rather than on a day:\n\n```\nDate = CALENDAR ( DATE ( 2020, 1, 1 ), DATE ( YEAR ( MAX ( Sales[Order Date] ) ), 12, 31 ) )\n```\n\nThis ends on the last day of the latest year in Sales, so the table spans full years, as [Microsoft's guidance](https://learn.microsoft.com/power-bi/guidance/model-date-tables) asks of a date table, and grows when a refresh brings a new year. [CALENDARAUTO](https://learn.microsoft.com/dax/calendarauto-function-dax#remarks) does the same from every date in the model outside calculated columns and tables, so a birth date or a placeholder such as December 31, 9999 stretches it too. To reach the end of the current year whether or not the data gets there yet, end CALENDAR on `DATE ( YEAR ( TODAY () ), 12, 31 )` instead.\n\nIn Power BI Desktop, select a measure, calculated column, or calculated table in the Data pane and edit its DAX in the formula bar. A calculation item is edited in Model view: select Model at the top of the Data pane to open [Model explorer](https://learn.microsoft.com/power-bi/transform-model/model-explorer#find-model-explorer), then select the calculation item under its calculation group, and its DAX opens in the DAX formula bar ([calculation groups](https://learn.microsoft.com/power-bi/transform-model/calculation-groups#add-a-new-calculation-group-in-model-view)). In TMDL, edit the expression after the object's `=`, or, for a date table, the `source` of its `calculated` partition.",
    ignore:
      'A fixed period is sometimes the point: a baseline year a measure compares against, a known event such as a change of data source or a day of bad data, a cohort such as customers whose first purchase was in 2023, a rule that changed in a given year, or sample data that never changes. A date table can end on purpose too, such as one that must stop at a contract\'s last day.\n\nOften the better move is a name that says so. An object whose name carries its year, such as `Sales 2024` or `Growth from 19/20`, reads as deliberate to anyone who opens the model, and the rule leaves it alone.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = HARDCODED_PERIOD_IN_DAX` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"HARDCODED_PERIOD_IN_DAX": "off"` under `rules` in `pbiplint.config.json`.',
  },
  HARDCODED_YEAR_IN_FILTER: {
    fix: "Filter the date, not the year, with a filter that moves with the calendar. In Power BI Desktop:\n\n1. Drag the date column, such as 'Date'[Date], from the Data pane into the section of the Filters pane that holds the year filter: Filters on this visual, Filters on this page, or Filters on all pages ([Add a filter to a visual](https://learn.microsoft.com/power-bi/create-reports/power-bi-report-add-filter#add-a-filter-to-a-visual)).\n2. On the date column's filter card, select Relative date from the Filter type drop-down ([Create the relative date range filter](https://learn.microsoft.com/power-bi/visuals/desktop-slicer-filter-date-range#create-the-relative-date-range-filter)).\n3. Under Show items when the value, choose is in this, then year.\n4. Remove the year filter. A filter you added can be deleted from the pane; a year that is one of the visual's own fields cannot be deleted, since the visual refers to it, so clear it instead ([Types of filters](https://learn.microsoft.com/power-bi/create-reports/power-bi-report-filter-types#compare-filter-types)).\n\nA relative date filter needs a column whose data type is a date, and it cannot use the auto date/time hierarchy, so for a filter on a date column's Year level, filter that date column itself ([Considerations and limitations](https://learn.microsoft.com/power-bi/visuals/desktop-slicer-filter-date-range#considerations-and-limitations)).\n\nWhen the filter keeps every year up to the latest one, as a range, an upper bound, or years picked one by one, it usually means every year from the first on. On its card, choose Advanced filtering, set the first condition to is greater than or equal to the first year, leave the second empty, and select Apply filter ([Add a filter to a visual](https://learn.microsoft.com/power-bi/create-reports/power-bi-report-add-filter#add-a-filter-to-a-visual)), so each new year is kept as it arrives.\n\nWhen the page should follow the latest year in the data rather than the calendar, as when data for a year lands weeks after it starts, or when the model has no date column, mark the year in the model instead. Right-click the date table in the Data pane, select New column, and enter the column's DAX in the formula bar ([Using calculated columns](https://learn.microsoft.com/power-bi/transform-model/desktop-calculated-columns#lets-look-at-an-example)):\n\n```\nIs Latest Year = 'Date'[Year] = YEAR ( MAX ( Sales[Order Date] ) )\n```\n\nThen drag Is Latest Year into the Filters pane in place of the year filter and keep True. For the calendar's current year, write `YEAR ( TODAY () )` in place of the MAX. Either way the flag moves at the first refresh of the new year, since, as Microsoft puts it for calculated columns, \"Column values are recalculated as necessary, like when the underlying data is refreshed and values have changed\" ([Using calculated columns](https://learn.microsoft.com/power-bi/transform-model/desktop-calculated-columns)).",
    ignore:
      'A fixed year is sometimes the point: a page or a visual about one year, such as a review of 2024; a baseline year others are compared with; a cohort; a series that has ended, such as figures that stopped being published; or sample data that never changes.\n\nOften the better move is a name that says so. A page whose name, or a visual whose title, carries one of the years its filter keeps, such as `Sales 2024` or `Review FY24`, reads as deliberate to every reader, and the rule leaves that filter alone.\n\nTo ignore this rule on one page or visual, add `{ "name": "pbiplint.ignore", "value": "HARDCODED_YEAR_IN_FILTER" }` to the `annotations` array of its page.json or visual.json. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"HARDCODED_YEAR_IN_FILTER": "off"` under `rules` in `pbiplint.config.json`.',
  },
  HIDDEN_VISUAL_WITH_FIELDS: {
    fix: "Find out first whether anything shows the visual. In Power BI Desktop, open the Bookmarks pane from the View tab and select each bookmark in turn, watching whether the visual appears. A bookmark can be linked to a button, a shape, or an image, on this page or another, so check the Action section in the Format pane of each one that has an action for the bookmark it applies. If a bookmark shows the visual, it is working as built; leave it.\n\nIf nothing does, delete it. Open the Selection pane from the View tab, select the eye icon beside the visual to show it, confirm it is the one you mean, and delete it from the page.\n\nA visual whose finding names a group is hidden because that group is. In the Selection pane, expand the group with the caret beside its name: while the group is hidden, the eye icons of the visuals in it are grayed out, so the visual cannot be shown on its own. Check the bookmarks for the group: a bookmark that shows the group usually shows the visual with it, but a bookmark saves each visual's own visibility too and can keep one visual in the group hidden, so select each bookmark that shows the group and watch whether the visual appears. If nothing shows the visual, select the group's eye icon to show the group, confirm the visual is the one you mean, delete it, and select the group's eye icon again to hide what is left. If a bookmark does show the visual, it is working as built. If the visual is meant to be seen while the group stays hidden, drag it out of the group in the Selection pane, so that it sits on the page on its own.",
    ignore:
      'A visual that a bookmark or a button reveals, by itself or with its group, is hidden on purpose, such as a detail table that a button shows on demand; ignore the finding on it. So is a hidden slicer kept to filter the page, since a slicer goes on filtering whether or not it is visible.\n\nTo ignore this rule on one visual, add `{ "name": "pbiplint.ignore", "value": "HIDDEN_VISUAL_WITH_FIELDS" }` to the `annotations` array of its visual.json. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"HIDDEN_VISUAL_WITH_FIELDS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  HIDE_FACT_TABLE_COLUMNS: {
    fix: "In Power BI Desktop, open the model view, select the column, and turn on Is hidden in the Properties pane, or right-click the column in the Data pane of report view and choose Hide. In the TMDL file, add `isHidden` under the column. The column is still loaded, still refreshed, and still available to every measure and relationship; it only leaves the field list.",
    ignore:
      'A numeric column readers use as an attribute rather than as a number is the case to keep visible: a Year on a date table, a Unit Price a report author slices by, a Rating people put on an axis. That a measure also aggregates the column somewhere does not make it the wrong field to pick. The rule does not test whether the table is a fact table either, so a dimension attribute that one measure happens to sum is reported on the same terms as a fact column. What to check before hiding is whether a report already binds a visual to the column, because hiding it does not break that visual but does remove the field from the list for whoever edits it next.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = HIDE_FACT_TABLE_COLUMNS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"HIDE_FACT_TABLE_COLUMNS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  HIDE_FOREIGN_KEYS: {
    fix: "In Power BI Desktop, open the model view, select the column, and turn on Is hidden in the Properties pane, or right-click the column in the Data pane and choose Hide in report view. In the TMDL file, add `isHidden` under the column. A hidden column still takes part in the relationship and still filters. It only leaves the field list.",
    ignore:
      'A key that people search or filter by in its own right can stay visible, for example an order number that is both the key to an Orders dimension and a value a reader types into a slicer. Ignore the finding on that column and leave the rule on for the rest of the model. A bare surrogate key is never something a report author needs to see.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = HIDE_FOREIGN_KEYS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"HIDE_FOREIGN_KEYS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  HIDE_TOOLTIP_DRILLTROUGH_PAGES: {
    fix: "In Power BI Desktop, right-click the page's tab and choose Hide Page. A hidden tooltip page still appears over the visuals it serves, and a hidden drillthrough page is still reached with Drill through on a data point; readers just cannot open either one directly.",
    ignore:
      'A drillthrough page that also works as a page in its own right, with a slicer of its own for choosing the item, can stay visible if it gives readers a way to clear the drillthrough filter it was last opened with, such as a button tied to a bookmark that removes the filters. Microsoft\'s drillthrough guidance describes that arrangement. A tooltip page has no such case, because it is never meant to be read on its own.\n\nTo ignore this rule on one page, add `{ "name": "pbiplint.ignore", "value": "HIDE_TOOLTIP_DRILLTROUGH_PAGES" }` to the `annotations` array of its page.json. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"HIDE_TOOLTIP_DRILLTROUGH_PAGES": "off"` under `rules` in `pbiplint.config.json`.',
  },
  INACTIVE_RELATIONSHIPS_THAT_ARE_NEVER_ACTIVATED: {
    fix: "Write the measure the relationship was put there for, so the second date has something that reads it:\n\n```\nShipped Sales = CALCULATE ( [Total Sales], USERELATIONSHIP ( Sales[Ship Date], 'Date'[Date] ) )\n```\n\nIn Power BI Desktop, choose New measure on the Home ribbon and type the expression in the formula bar. In the TMDL file, add the `measure` block to the fact table. Name the columns in the order the relationship declares them, its from column first. DAX takes them either way round, but only that order counts as activation here.\n\nWhere nothing needs the relationship, delete it instead: open the model view, right-click the dotted line, and choose Delete, or remove its `relationship` block from the TMDL file.",
    ignore:
      'This rule reads the semantic model, not the reports built on it. A report-level measure in a live-connected report can call USERELATIONSHIP, and the rule cannot see it, so check the reports before deleting a relationship that looks unused. The same goes for a relationship activated from a calculated column, a calculated table, or a row-level security filter: none of those is scanned here, and a finding on one of them is noise. A relationship added this week for measures that are still being written is a fair thing to leave alone for a sprint.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = INACTIVE_RELATIONSHIPS_THAT_ARE_NEVER_ACTIVATED` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"INACTIVE_RELATIONSHIPS_THAT_ARE_NEVER_ACTIVATED": "off"` under `rules` in `pbiplint.config.json`.',
  },
  INTEGER_FORMATTING: {
    fix: "Set a format string that matches what the measure represents: `#,0` for counts and other whole numbers, a currency format such as `$#,0.00` for money, or `#,0.0%;-#,0.0%;#,0.0%` for percentages, which is the exact string `PERCENTAGE_FORMATTING` expects. In Power BI Desktop, select the measure in the Data pane and type the string into the Format box under Measure tools. In the TMDL file the property is `formatString: #,0` under the measure.",
    ignore:
      'A measure already formatted the way its number deserves is the usual false alarm. Only two plain number formats pass, so an average carrying two decimals as `#,0.00`, a rate written `0.000`, and a price in a currency whose symbol is not the dollar sign are all reported although each is formatted on purpose. Look at the detail on the finding before deciding: `no format string` is always worth fixing, while a format string the rule merely does not recognize is a question of house style. A measure that returns text rather than a number has no format to set at all.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = INTEGER_FORMATTING` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"INTEGER_FORMATTING": "off"` under `rules` in `pbiplint.config.json`.',
  },
  ISAVAILABLEINMDX_FALSE_NONATTRIBUTE_COLUMNS: {
    fix: "Add `isAvailableInMdx: false` under the column in its table's TMDL file. Power BI Desktop has no setting for the property and never writes it, but it keeps the value once it is in the file, and it keeps it the same way on an import table and a DirectQuery one. The other way to clear a finding is to decide the column should not be hidden after all: clear Is hidden in the Properties pane, or remove `isHidden` from under the column, and the rule stops reading it, as long as its table is visible too. Where a table has dozens of hidden keys, Tabular Editor's property grid sets the property on every selected column in one edit, which is quicker than the same change repeated down a file.",
    ignore:
      "Size is the first judgment. The saving is roughly proportional to the column's distinct count, so a hidden flag with two values is not worth an edit and a hidden key with a million is. Work down the list by cardinality and stop where the numbers get small. A variation is the one case where acting on the finding can break something: pbiplint reads a variation's default column only, so a hidden column a variation reaches through its default hierarchy is reported here, and setting the property to false on it takes away the attribute hierarchy the variation needs. Check the date table's hidden columns against its variations before you touch them. A column you are about to unhide is a fair thing to leave, since unhiding it clears the finding anyway, as long as its table is visible. A table in Direct Lake storage mode is a judgment of its own: Direct Lake loads a column's data when a query needs it, and its refresh copies only metadata, so the refresh time this rule is about is not spent the same way (see Quirks).\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = ISAVAILABLEINMDX_FALSE_NONATTRIBUTE_COLUMNS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"ISAVAILABLEINMDX_FALSE_NONATTRIBUTE_COLUMNS\": \"off\"` under `rules` in `pbiplint.config.json`.",
  },
  LANDING_PAGE_NOT_SET: {
    fix: "In Power BI Desktop, right-click the tab of the page readers should start on and select Set as landing page; an icon on the tab marks it. Or, with nothing selected on the page, open the Format pane, expand Page information, and turn on Landing page. Only one page can be the landing page, so setting another moves it.",
    ignore:
      'A report with a single page opens on that page whatever pages.json says, so a landing page adds nothing there. Ignore the finding on a one-page report you do not expect to grow.\n\nThis rule reports on the report itself, so there is no object to annotate. To turn the rule off for a whole project, set `"LANDING_PAGE_NOT_SET": "off"` under `rules` in `pbiplint.config.json`.',
  },
  LARGE_TABLES_SHOULD_BE_PARTITIONED: {
    fix: "Find the row count first. In Power BI Desktop's DAX query view, run a query such as `EVALUATE ROW(\"rows\", COUNTROWS('Sales'))` for each table you suspect. Then set up incremental refresh on the ones that are large: define the RangeStart and RangeEnd date parameters in Transform data, filter the table's date column between them, and close and apply; back in the report view, right-click the table in the Data pane, choose Incremental refresh, and set how much history to keep and how much of it to reload each time. In the TMDL file the result is a `refreshPolicy` block under the table beside its one partition, and the dated partitions themselves are created by the service when the model is refreshed after publishing, so a project's files keep showing a single partition. A table that is large but has no date column to range over is partitioned by hand instead, by writing one `partition` block per slice with its own filtered `source`. DAX Studio's VertiPaq Analyzer reads the row count of every table at once if you would rather start from a list than a query per table, and if you already use Tabular Editor, the walkthrough under Links loads the same statistics into its Best Practice Analyzer, which can then run this rule directly.",
  },
  "LIMIT_ROW_LEVEL_SECURITY_(RLS)_LOGIC": {
    fix: "Precompute the value the filter is deriving, then compare it with equals. In Power BI Desktop, choose Transform data, select the query behind the secured table, and add the derived column there with Add Column, Custom Column, or better still add it to the view the query reads so every model gets it. Then, under Modeling, Manage roles, rewrite the filter as a plain comparison such as `'Employee'[Email] = USERPRINCIPALNAME()`; in the TMDL file that is the text after the `=` on the role's `tablePermission` line. The example above is the common one: DAX compares text without regard to letter case, so the two UPPER calls were doing nothing the equals sign did not already do, and the fix is to delete them. Where the string work is real, for example taking the domain off an address, do it in the query and leave the filter as one comparison. The route is the same for an import table and a DirectQuery one, though on DirectQuery the derived column has to fold, so the source view is the safer place for it.",
    ignore:
      'Where the function is applied to the user\'s name rather than to a column, the finding is noise. An expression such as `\'Employee\'[Domain] = RIGHT(USERPRINCIPALNAME(), LEN(USERPRINCIPALNAME()) - FIND("@", USERPRINCIPALNAME()))` evaluates the string work once per query, not once per row, which is the cost the rule is about. A small secured table is the second case: a few hundred rows of a security table cost little however the filter is written, so measure with the role applied before you rebuild a query. What is not worth ignoring is a string function applied to a column of a large fact or dimension table, because that is the row-by-row evaluation the rule was written for, and the table only gets bigger.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = LIMIT_ROW_LEVEL_SECURITY_(RLS)_LOGIC` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"LIMIT_ROW_LEVEL_SECURITY_(RLS)_LOGIC": "off"` under `rules` in `pbiplint.config.json`.',
  },
  "MANY-TO-MANY_RELATIONSHIPS_SHOULD_BE_SINGLE-DIRECTION": {
    fix: "In Power BI Desktop, open the model view, double-click the relationship, and set Cross filter direction to Single in the Edit relationship dialog. In the TMDL file that is the `crossFilteringBehavior: bothDirections` line under the relationship, deleted; single direction is the default and needs no line of its own. Check which way the one direction then runs: with single direction the filter travels from the relationship's to column toward its from column, which are the `toColumn` and `fromColumn` lines in the file and the two ends of the arrow in the model view. Where a report needed the reverse filter, put it in the measure instead of the model, as in `Budget In Scope = CALCULATE(SUM('Regional Budget'[Budget]), CROSSFILTER('Customer'[Region], 'Regional Budget'[Region], BOTH))`, so one visual pays for it rather than every query. Better again, load a region table with one row per region and relate both tables to it many-to-one, which removes the many-to-many relationship and the question with it.",
    ignore:
      'A bridge that has to filter upward is the legitimate case: a security table that must narrow a dimension, or a mapping table between two dimensions that a slicer has to reach through. Both are designs where the reverse direction is the whole point, and neither is fixed by the rule\'s advice. Before you ignore one, trace the model view for a second path between the same two tables, because the ambiguity this rule guards against only exists when there are two, and one bridge with one path is safe. Ignore the finding on that relationship and leave the rule on: the next bi-directional many-to-many relationship someone adds is the one you want to hear about.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = MANY-TO-MANY_RELATIONSHIPS_SHOULD_BE_SINGLE-DIRECTION` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"MANY-TO-MANY_RELATIONSHIPS_SHOULD_BE_SINGLE-DIRECTION": "off"` under `rules` in `pbiplint.config.json`.',
  },
  MARK_PRIMARY_KEYS: {
    fix: "Add `isKey` under the column in the TMDL file. Power BI Desktop has no box for the property on an ordinary table, and it keeps the value once it is in the file; the one place Desktop sets a key itself is Mark as date table, which sets it on the date column of the table you mark and takes that table out of this rule at the same time. Check that the column really is unique before you set it, because the engine takes the property at its word. Tabular Editor exposes the property in its property grid, which is a quicker way to set it across the dimensions of a large model than editing each file.",
    ignore:
      'A dimension you cannot yet guarantee is unique is the case to leave alone. If the table is loaded from a feed that occasionally repeats a row, the key property turns a silent double-count into a loud failure, which is the right trade once the source is under control and the wrong one while you are still chasing it. Check the distinct count against the row count before you set the property, not after. A calendar table is the other case: mark it as a date table instead, which sets the key on its date column and takes the table out of the rule.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = MARK_PRIMARY_KEYS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"MARK_PRIMARY_KEYS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  MEASURES_SHOULD_NOT_BE_DIRECT_REFERENCES_OF_OTHER_MEASURES: {
    fix: "Repoint the visuals that use the alias at the original, then delete it. In Power BI Desktop, right-click the alias in the Data pane and choose Delete from model. In the TMDL file, remove its `measure` block from the table.\n\nWhere the alias exists only because its name is the better one, do the rename the other way around: rename the original and delete the alias. Select the original in the Data pane, press F2, and type the new name, and Desktop repoints the visuals that use it. In the TMDL file the name is on the declaration line, so `measure 'Total Sales' =` becomes `measure Revenue =`, and a hand edit there does not update the report, so open the report and check its visuals afterwards.",
    ignore:
      'A rename in progress is the case that holds up: the alias keeps published reports working until each one is repointed, and it goes the day the last one moves. Give it an end date rather than leaving it. The argument that the alias puts the number in a second place in the field list does not hold, because the original\'s home table and display folder are both properties you can set on it, which is the same result without a second definition.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = MEASURES_SHOULD_NOT_BE_DIRECT_REFERENCES_OF_OTHER_MEASURES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"MEASURES_SHOULD_NOT_BE_DIRECT_REFERENCES_OF_OTHER_MEASURES": "off"` under `rules` in `pbiplint.config.json`.',
  },
  MEASURES_USING_TIME_INTELLIGENCE_AND_MODEL_IS_USING_DIRECT_QUERY: {
    fix: "Either take the model out of DirectQuery or take the time intelligence out of the measure. For the first, select the table in Power BI Desktop's model view and set Storage mode to Import in the Properties pane, which is the partition's `mode: import` line in the TMDL file; the finding clears only once no table in the model is left in DirectQuery, because the condition is about the model and not about the tables the measure happens to read. For the second, move the comparison into the data: add the prior period's value to each row in the source view or the warehouse, load it as an ordinary column, and write the measure as a SUM over it, which is what the example above does. Where neither is possible, keep the number of time intelligence measures on one page small and cache what you can in the source, because every one of them is another round trip.",
    ignore:
      'The common false alarm is a measure that has nothing to do with the DirectQuery table. The rule reads the model, not the query path, so one small DirectQuery table kept for real-time status will report every time intelligence measure in the model, including the ones that run entirely over imported tables. Check which tables the measure actually touches before you act on it. A source that answers quickly is the second case: a well-indexed warehouse over a few million rows returns a year-to-date query in well under a second, and a page that renders fast is not a problem whatever the rule says. Time the visual before rewriting anything. What is not a legitimate exception is a large DirectQuery fact table over a source you do not control, where the finding is naming the reason the report is slow.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = MEASURES_USING_TIME_INTELLIGENCE_AND_MODEL_IS_USING_DIRECT_QUERY` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"MEASURES_USING_TIME_INTELLIGENCE_AND_MODEL_IS_USING_DIRECT_QUERY": "off"` under `rules` in `pbiplint.config.json`.',
  },
  MINIMIZE_POWER_QUERY_TRANSFORMATIONS: {
    fix: "Move the work to the source. Create a view that does the join, the grouping, or the pivot, then in Power BI Desktop choose Transform data, point the query at the view, and delete the steps the view now does, so the Applied steps list is Source and little else. In the TMDL file the same text is the partition's `source` block, which is what Transform data edits. Where a step has to stay in Power Query, check that it still folds: right-click the last step in Applied steps and look at View native query, which is greyed out once folding has stopped at or before that step, and move everything after that point upstream. A native SQL query is its own case, because what folds after one depends on the connector; the safer shape is a view the query simply reads, which folds like any other table. Where the source is a file or a folder and there is nowhere upstream to move anything, leave the steps and read the finding as a note about why the refresh takes what it takes.",
    ignore:
      'Where there is no upstream to move to, the finding is noise. A folder of CSV exports combined with Table.Combine, a SharePoint list, a workbook someone maintains by hand, an API that returns records to expand: none of these has a view behind it, and Power Query is the only place the work can happen. A step that folds is the second case: Table.Group over a SQL source turns into GROUP BY and costs the refresh nothing, so check View native query before rewriting anything. Size is the third judgment: on a dimension of a few thousand rows the whole question is worth less than the time spent on it. The case to act on is a large fact table whose query folds up to a point and then stops, which is where the rule pays for itself.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = MINIMIZE_POWER_QUERY_TRANSFORMATIONS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"MINIMIZE_POWER_QUERY_TRANSFORMATIONS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  MODEL_SHOULD_HAVE_A_DATE_TABLE: {
    fix: "Add a date table with one row per day covering every date the model holds, then mark it. The first-choice route is the source: load a date view or table in Transform data, so the fiscal periods and holidays live where the rest of the business already agrees on them. Failing that, build one in Power Query from a list of dates, or in Power BI Desktop under Modeling, New table with DAX such as `Date = CALENDAR(DATE(2020, 1, 1), DATE(2030, 12, 31))`; New table needs a table in import storage mode, so a model whose tables are all DirectQuery has to take the date table from the source. Then select the table, open Table tools, choose Mark as date table, and pick the date column, which writes `dataCategory: Time` on the table and `isKey` on that column in the file. Finish by relating each fact table's date column to it in the model view and turning off Auto date/time under File, Options and settings, Options, Data Load, so the hidden per-column date tables stop being built. Where the model uses calendar-based time intelligence, a preview in Power BI Desktop, define a calendar on the date table instead, under Calendar options in Table tools, which writes a `calendar` block under the table in its file ([Calendar-based time intelligence](https://learn.microsoft.com/power-bi/transform-model/desktop-time-intelligence#calendar-based-time-intelligence-preview)). Calendar options appears only once the Enhanced DAX Time Intelligence preview is turned on, under File, Options and settings, Options, Preview features ([Enable the enhanced DAX Time Intelligence preview](https://learn.microsoft.com/power-bi/transform-model/desktop-time-intelligence#enable-the-enhanced-dax-time-intelligence-preview)).",
    ignore:
      'A model with no dates in it is the clean exception: a reference list, a product catalogue published for other models to join to, a survey result set. There is no time intelligence to do and no date table would have anything to cover. A model that answers only current-state questions, such as a stock-on-hand report with no period comparison anywhere, is the same judgment made deliberately rather than by omission. Everything else that shows a trend, a year-to-date figure, or a comparison with last year needs the table, and the reason the rule is at warning is that the alternative, Auto date/time, works well enough in a demo to hide the problem until someone asks for a fiscal year.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = MODEL_SHOULD_HAVE_A_DATE_TABLE` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"MODEL_SHOULD_HAVE_A_DATE_TABLE": "off"` under `rules` in `pbiplint.config.json`.',
  },
  MODEL_USING_DIRECT_QUERY_AND_NO_AGGREGATIONS: {
    fix: "Build a summary table at the grain the reports use most, one row per day and region rather than one per transaction, and load it from a view in the source so the two tables stay consistent. Import it, keep the detail table in DirectQuery, and in Power BI Desktop right-click the summary table in the model view, choose Manage aggregations, and map each of its columns to the detail column it summarizes and the function that summarizes it. In the TMDL file that mapping is an `alternateOf` block under each aggregation column, which is the only thing the rule looks for. The block names the detail column in `baseColumn`, qualified by its table as in `Sales.'Order Date'`, or, for Count table rows, names the detail table alone in `baseTable`. It sets a `summarization`, such as `sum` or `count`, for every function except group by, which it leaves out. The summary table should be hidden, because report authors write their measures against the detail table and the engine redirects the query when it can. The Manage aggregations dialog hides it for you when you select Apply all, if it is not hidden already; in the TMDL file that is `isHidden` on the table, as in the example. Any one aggregation mapping anywhere in the model clears this finding, so treat the rule as a prompt to start rather than a measure of how far you got.",
    ignore:
      'The question is whether there is a summary worth precomputing. A DirectQuery table kept for a handful of live status tiles has none: the whole point is that the numbers are current to the second, and a cached summary would be wrong. A report that only ever reads detail rows, such as a lookup of one order by number, has none either, because there is no total for an aggregation to answer. A source that already serves a summarized view at the grain the report asks for is the third case, and there the aggregation exists, it is just on the other side of the connector. Where the report opens on a page of totals by month over a large DirectQuery fact table, the finding is worth acting on, and at info severity it will not fail a build while you decide.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = MODEL_USING_DIRECT_QUERY_AND_NO_AGGREGATIONS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"MODEL_USING_DIRECT_QUERY_AND_NO_AGGREGATIONS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  "MONTH_(AS_A_STRING)_MUST_BE_SORTED": {
    fix: "Add a month number column to the table, hide it, then in Power BI Desktop select the month name column and pick the number under Sort by column in Column tools. In the TMDL file the property is `sortByColumn: 'Month Number'` under the month name column. Each month name has to map to exactly one number, so a name like January that appears in several years needs a number column at the same grain, 1 through 12, not a year-month key; Power BI rejects the sort otherwise. Where the axis runs across years, sort a Month Year column by a year-month number instead and leave the plain month name for the within-year views.",
    ignore:
      'A text column the name test catches that is not a list of month names is noise: a Monthly Target note, a Month Comment, anything where alphabetical order is as good as any other. A month column whose values already sort correctly is the other case, such as one holding 2026-01 and 2026-02, where a sort-by column would only add a second column to maintain. Where the values are month names, there is no reason to leave the sort alphabetical.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = MONTH_(AS_A_STRING)_MUST_BE_SORTED` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"MONTH_(AS_A_STRING)_MUST_BE_SORTED": "off"` under `rules` in `pbiplint.config.json`.',
  },
  MONTHCOLUMN_FORMATSTRING: {
    fix: "In Power BI Desktop, select the column in the Data pane and set Format under Column tools. In the TMDL file, add `formatString: MMMM yyyy` under the column. The column keeps its DateTime type and its value, so it still sorts chronologically and still works in a relationship to the date table; only what a visual prints changes.",
    ignore:
      'A DateTime column with month in its name that holds a full date, not a month start, is the case to leave alone: formatting Month End Date as `MMMM yyyy` throws away the day, which is the part a reader needs. House style is the other case, where a model already writes its month labels as `MMM yyyy` and changing them would leave two conventions in the same report. A hidden month column shows nothing to anyone, so its format string is not worth a change on its own.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = MONTHCOLUMN_FORMATSTRING` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"MONTHCOLUMN_FORMATSTRING": "off"` under `rules` in `pbiplint.config.json`.',
  },
  NAME_WITHOUT_TRANSLATION: {
    fix: "Give the object a `caption` in the culture's `translations` block. Power BI Desktop has no editor for translations, and Microsoft gives its TMDL view as the route for metadata that lacks a graphical interface, \"such as translations\" ([Common use cases for TMDL view](https://learn.microsoft.com/power-bi/transform-model/desktop-tmdl-view#common-use-cases-for-tmdl-view)). In TMDL view, type `createOrReplace` on the first line of an empty tab, paste the whole `cultureInfo` block from `definition/cultures/<culture>.tmdl` beneath it, and indent the pasted lines one level, so the block sits under the command. Then give each object with no caption an entry in its place, with a `caption:` line one level beneath the entry, as the fixed example adds `measure Revenue` under `table Sales`: a table's entry goes under the `model` entry, a column's, measure's, or hierarchy's under its table's entry, and a level's under its hierarchy's entry. Where the block already has the object's entry, as it has a table's once any of the table's objects is captioned, add only the `caption:` line. Select Apply. Script the whole block: `createOrReplace` \"Creates or replaces the specified semantic model objects and all the descendants\" ([CreateOrReplace command](https://learn.microsoft.com/analysis-services/tmdl/tmdl-scripts#createorreplace-command)), so a script of part of it drops the captions it leaves out. Or edit the culture's file while Desktop is closed. For many objects at once, Microsoft's Translations Builder, an optional tool, can fill in captions, machine translations included ([Create multiple-language reports with Translations Builder](https://learn.microsoft.com/power-bi/guidance/translation-builder)).",
    ignore:
      'When the culture\'s names are not meant for readers yet, such as a translation still in progress, or a culture kept for another purpose that happens to carry a `translations` block. Otherwise a visible object with no caption is one a reader in that language sees untranslated. A key or helper column no reader needs is better hidden than translated, which clears its finding too.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = NAME_WITHOUT_TRANSLATION` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"NAME_WITHOUT_TRANSLATION": "off"` under `rules` in `pbiplint.config.json`.',
  },
  NOT_REACHED_FROM_REPORT: {
    fix: "Check first that nothing outside this report needs the field: another report built on the same model, a paginated report, or an Excel workbook that reads the model. Removing a column that something else uses breaks that thing, and pbiplint sees only the report in front of it.\n\nThen remove the field from the model. In Power BI Desktop, right-click the measure or calculated column in the Data pane, or select it in Model view, and choose Delete from model. For a column that Power Query loads, open Power Query Editor, select the column in the table's query, and choose Remove Columns, so it is no longer loaded at all. If a hierarchy level uses the column, first select the hierarchy in Model view and, in the Properties pane, set its levels without that column, then select Apply Level Changes. In the TMDL files, delete the `measure` or `column` block from the table's file, and, for a column Power Query loads, remove it from the table's query as well. When the finding names a level of a user hierarchy, also delete that `level` block, which sits under its `hierarchy` block in the same file and names the column on its `column:` line, or point that `column:` at another column of the same table. A dead chain is listed with its measures before its columns, so one pass down the list removes all of it. When a detail names a user-defined function, as in `referenced only by Sales.NetAfterReserve, which nothing reaches either`, nothing reaches that function either, and it has no finding of its own: delete its `function` block from `definition/functions.tmdl` too, or edit it so it no longer names the fields you delete, since a function that names a field the model no longer has breaks.",
    ignore:
      'A measure kept for another report on the same model, or for people who analyze the model in Excel, is not dead because this report does not use it, and neither is a column that a paginated report or a workbook reads. When several reports share the model, a finding here says only that this report does not reach the field; weigh it against the others before deleting anything, and ignore it on the fields they need.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = NOT_REACHED_FROM_REPORT` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"NOT_REACHED_FROM_REPORT": "off"` under `rules` in `pbiplint.config.json`.',
  },
  NUMERIC_COLUMN_SUMMARIZE_BY: {
    fix: "In Power BI Desktop, select the column in the Data pane and set Summarization to Don't summarize under Column tools. In the TMDL file the property is `summarizeBy: none` under the column. Where the column really is a number reports need totals of, add an explicit measure for it, because the point of the change is that the aggregation becomes something the model defines rather than something a visual guesses.",
    ignore:
      'An additive column with no measure behind it is the case to weigh. On a small planning or budget table that a handful of people build their own matrices from, the implicit sum is the feature, and taking it away without writing the measures first makes the model harder to use, not safer. Check which reports drag the column in before you change it. A year, a key, a price, or a rate is never that case: summing any of them produces a number with no meaning, and those are the findings to act on first.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = NUMERIC_COLUMN_SUMMARIZE_BY` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"NUMERIC_COLUMN_SUMMARIZE_BY": "off"` under `rules` in `pbiplint.config.json`.',
  },
  OBJECTS_SHOULD_NOT_START_OR_END_WITH_A_SPACE: {
    fix: "In Power BI Desktop, double-click the field in the Data pane and retype the name without the space, or select the object and clear the space from Name in the Properties pane. In the TMDL file the name is on the declaration line, so `column 'Order ID '` becomes `column 'Order ID'`. A data column carries its own `sourceColumn`, so trimming the model name does not change what the refresh loads. Renaming in Desktop updates the visuals bound to the field; a hand edit in the file does not, so open the report and check its visuals after one. Where the space arrives with a source column name, trim it in Power Query too, so the next column you add from that query comes in clean.",
    ignore:
      'No name should start or end with a space, and this rule reports at error severity because a name that reads as correct and is not costs more to diagnose than to fix. A leading space is sometimes used to push a measure to the top of the field list; a display folder puts the measure where it belongs without hiding a character in its name.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = OBJECTS_SHOULD_NOT_START_OR_END_WITH_A_SPACE` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"OBJECTS_SHOULD_NOT_START_OR_END_WITH_A_SPACE": "off"` under `rules` in `pbiplint.config.json`.',
  },
  OBJECTS_WITH_NO_DESCRIPTION: {
    fix: "In Power BI Desktop, open Model view, select the object, and type the Description in the Properties pane. In the TMDL file a description is one or more `///` lines directly above the object's declaration, with no blank line between the last `///` line and the declaration: a blank line ends the description, and the object below it is read as having none. With hundreds of objects, Tabular Editor can paste descriptions into many at once from a list.",
    ignore:
      'A name that already says the whole thing needs nothing added: `\'Date\'[Year]` gains nothing from a sentence reading "the year". Spend the descriptions on measures, on any column whose unit, currency, grain, or filter behavior is not in its name, and on the two fields a reader has to choose between. A table or column you are about to hide is better hidden than described, because hiding it also clears this finding.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = OBJECTS_WITH_NO_DESCRIPTION` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"OBJECTS_WITH_NO_DESCRIPTION": "off"` under `rules` in `pbiplint.config.json`.',
  },
  OPENING_PAGE_INVALID: {
    fix: "In Power BI Desktop, set a visible landing page: right-click the tab of the page readers should start on and select Set as landing page, or, with nothing selected on the page, open the Format pane, expand Page information, and turn on Landing page. The report then opens there whatever page is active when it is saved. Without a landing page, open a visible page before you save, so that page becomes the active one.",
    ignore:
      'When readers are meant to start on a hidden page, make it the landing page: Power BI supports a hidden landing page, and this rule does not report one. Short of that, there is no case for keeping the finding, because a report that opens on a missing page, or on a helper page by accident, starts every reader in the wrong place.\n\nThis rule reports on the report itself, so there is no object to annotate. To turn the rule off for a whole project, set `"OPENING_PAGE_INVALID": "off"` under `rules` in `pbiplint.config.json`.',
  },
  PARSE_ISSUE: {
    fix: "Open the file at the reported line. TMDL is indented with tabs, and a fenced expression opens with three backticks (```) after the `=` and closes with three backticks on a line of its own; an unterminated code fence names the declaration whose fence never closes, so add that line where its expression ends. Only a few types sit at the root of a TMDL file, such as `table`, `relationship`, and `role`: correct the word the finding names, or, when it names something that belongs inside another object, such as a `column`, indent it one tab deeper than that object's line. Under any other object the same holds for the objects it holds: a table holds columns, measures, hierarchies, and partitions, a hierarchy its levels, a role its members and table permissions, so correct a misspelt word such as `columm`, or move a line such as a `level` back under the object it belongs to. The same types may sit one tab under the `model` line instead, and no declaration but the model under the `database` line: move any other declaration named there to the root of a file, or to the object it belongs to. A `table` line reported under another object has gained a tab: move it back to the start of the line, with the lines under it one tab shallower too. A declaration with no name needs its name back, and a name with a space, a dot, an equals sign, a colon, or a single quote in it is enclosed in single quotes, with each quote inside doubled, as in `'O''Brien'`. A property or child object sits one tab deeper than the object it belongs to, and a multi-line expression one tab deeper than that object's properties, so check the lines under it by the same rule. A `///` description must sit directly above its declaration, with no blank line between them. Power BI Desktop writes valid TMDL, so a parse issue usually means a hand edit or a merge conflict marker. In a report JSON file, the finding names the file and the line where the JSON stops being valid, where a conflict marker sits, where the document passes 256 levels of nesting, or where a document that is not a JSON object starts. Resolve the conflict or restore the JSON at that line. This is one of two report pages whose fix names a file rather than a step in Power BI Desktop (`REPORT_LEVEL_MEASURES` is the other): Desktop cannot open a project holding a file that is not valid JSON, so the file has to be repaired before Desktop can help. Power BI Desktop's own files nest a few dozen levels at most, so a file nested past 256 was generated or edited outside Desktop: restore it from version control, or rebuild what it holds in Desktop and save the report again. A file whose content is not an object needs its object restored, for example from version control: Microsoft's schema for each file it defines in a report's definition folder puts a JSON object at its root. A reportExtensions.json that lists no entity holds no report measure: delete the file. Power BI Desktop does not open a project whose reportExtensions.json has an empty `entities` list, and opens it once the file is gone (checked on October 3, 2026 in Power BI Desktop 2.158, the September 2026 release). A file with no `entities` list at all is reported the same way. Then reopen the report in Power BI Desktop to confirm that it loads.",
    ignore:
      'Not on purpose. A parse issue means the model pbiplint checked is not the model in the file, or, in a report JSON file, that nothing the file defines was checked (a reportExtensions.json that lists no entity is the exception: it is read, and defines no measure), so every other result on that file is in doubt until the line is fixed. The one exception is a line that Power BI Desktop wrote and opens without complaint and pbiplint still reports, in a TMDL file or a report JSON file: that is a gap in pbiplint\'s parser. Report it with the line. Until it is fixed, only the project-wide switch quiets it, and that also hides real parse issues, so weigh the two.\n\nThis rule reports on files, so there is no object to annotate. To turn the rule off for a whole project, set `"PARSE_ISSUE": "off"` under `rules` in `pbiplint.config.json`.',
  },
  PARTITION_NAME_SHOULD_MATCH_TABLE_NAME_FOR_SINGLE_PARTITION_TABLES: {
    fix: "The partition's name sits on its declaration line, so `partition SalesData = m` under `table Sales` becomes `partition Sales = m`. Nothing else in the TMDL file refers to a partition by name, so on a single-partition table the rename changes nothing but the label in the refresh log. Power BI Desktop has no partition list and no field for a partition name: it names the partition when it creates the table and leaves the name alone afterwards, so a mismatch on a Desktop project points at a hand edit, a table renamed outside Desktop, or a model migrated from another tool. If a whole model needs correcting, Tabular Editor's partition editor renames partitions without opening each file.",
    ignore:
      'A partition that the people who run the refresh already know by another name can keep it, for example one named after the stored procedure that fills it, because that is the name they will look for when the refresh fails. Outside that, a single partition named anything but its table is a leftover, and the rename costs nothing.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = PARTITION_NAME_SHOULD_MATCH_TABLE_NAME_FOR_SINGLE_PARTITION_TABLES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"PARTITION_NAME_SHOULD_MATCH_TABLE_NAME_FOR_SINGLE_PARTITION_TABLES": "off"` under `rules` in `pbiplint.config.json`.',
  },
  PERCENTAGE_FORMATTING: {
    fix: "Use the format string `#,0.0%;-#,0.0%;#,0.0%`. In Power BI Desktop, select the measure in the Data pane and paste the string into the Format box under Measure tools. In the TMDL file, set `formatString: #,0.0%;-#,0.0%;#,0.0%` under the measure. The three parts are the positive, negative, and zero cases in that order, which is why the string repeats itself: it says how each of the three is rendered rather than leaving two of them to a default.",
    ignore:
      'A percentage that needs a different precision is the honest exception: a conversion rate people read to two decimals, or a completion figure that reads better as a whole number on a card. If that is the house standard, every percentage measure in the model fires and the rule is measuring the wrong convention, which is worth settling once for the whole model rather than card by card. What is not an exception is a single measure left at the client default because nobody chose a format for it.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = PERCENTAGE_FORMATTING` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"PERCENTAGE_FORMATTING": "off"` under `rules` in `pbiplint.config.json`.',
  },
  PERSPECTIVES_WITH_NO_OBJECTS: {
    fix: "Power BI Desktop has no graphical editor for perspectives, and its TMDL view is the route Microsoft gives ([Common use cases for TMDL view](https://learn.microsoft.com/power-bi/transform-model/desktop-tmdl-view#common-use-cases-for-tmdl-view)). A perspective is a `perspective` block of its own, and the objects it shows are `perspectiveTable` entries under it, with the columns, measures, and hierarchies it shows listed beneath each one. In TMDL view, write a `createOrReplace` script of the whole perspective with the tables it should show, and select Apply. To remove the perspective instead, close Desktop, delete its file from the `perspectives` folder, and drop the matching `ref perspective` line from `model.tmdl`. Tabular Editor edits perspectives in a UI if you would rather tick boxes than edit the file.",
    ignore:
      'There is no case for it. A perspective you have created and not yet filled is the one you want reported, because nothing else will tell you it is still empty, and an empty perspective in a published model offers a report author a view of the model with no fields in it.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = PERSPECTIVES_WITH_NO_OBJECTS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"PERSPECTIVES_WITH_NO_OBJECTS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  PROVIDE_FORMAT_STRING_FOR_MEASURES: {
    fix: "In Power BI Desktop, select the measure in the Data pane and set Format under Measure tools. In the TMDL file, add `formatString` under the measure: `#,0` for whole numbers, `#,0.00` for decimals, a currency format such as `$#,0.00`, or `#,0.0%;-#,0.0%;#,0.0%` for percentages. Where the format depends on what the measure returns, a dynamic format string satisfies the rule as well: pick Dynamic in the Format list under Measure tools and write the expression in the formula bar, which the file records as a `formatStringDefinition` block under the measure.",
    ignore:
      'A measure that returns text has nothing to format. pbiplint leaves out the ones whose DAX shows it plainly (see Quirks), but a label that comes from a column, such as `MAXX` over a text column, and a measure that picks a hex color for conditional formatting with `SWITCH` or `IF`, are still reported, and neither has a number behind it. Everything else the rule reports is a visible number a reader will see, so the finding is usually worth the ten seconds it takes to clear.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = PROVIDE_FORMAT_STRING_FOR_MEASURES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"PROVIDE_FORMAT_STRING_FOR_MEASURES": "off"` under `rules` in `pbiplint.config.json`.',
  },
  REDUCE_ADVANCED_FILTERS: {
    fix: "Where a condition picks out a group the report keeps coming back to, such as bikes, put the group in the model: add a column in Power Query (in Power BI Desktop, Transform data, then Add Column) that names the group for each product, and filter that column with Basic filtering, which picks values instead of matching text. Where several visuals share one condition, state it once in the Filters pane under Filters on this page, where a reader can see it, and remove it from each visual. A condition nobody needs any more can be cleared with the eraser on its filter card.",
    ignore:
      'A condition on a short column of an Import model, such as a category name, is cheap to apply, and so is a measure condition over a few dozen items. A page built to compare one measure under different conditions, visual by visual, needs its filters where they are. Check the page with Performance Analyzer in Power BI Desktop, and ignore the finding when the filtered visuals come back quickly.\n\nTo ignore this rule on one page, add `{ "name": "pbiplint.ignore", "value": "REDUCE_ADVANCED_FILTERS" }` to the `annotations` array of its page.json. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"REDUCE_ADVANCED_FILTERS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  REDUCE_NUMBER_OF_CALCULATED_COLUMNS: {
    fix: "Move the work upstream. In Power BI Desktop choose Transform data, select the query, and use Add Column, Custom Column, or one of the ready-made transforms such as Extract or Round, then delete the DAX column: right-click it in the Data pane and choose Delete from model, or remove its `column Name = expression` block from the table's TMDL file. Better still, add the expression to the view the query reads, where it computes once for every model that reads the view and folds into the refresh rather than running after it. Date parts are the common case and have a third home: year, month, and week belong on the date table, related to the fact table, rather than repeated on every fact row. Keep DAX calculated columns for the few cases that need the model, such as a value that depends on a measure or on a relationship.",
    ignore:
      'Five is somebody\'s round number, not a law, and a model can be perfectly healthy at eight. The judgment is what the columns cost, which the rule cannot see: six columns on a two-thousand-row dimension are free, and one on a hundred-million-row fact table is the thing to look at first. A column that genuinely needs the model is the other legitimate case: a value derived from a measure, or a flag that depends on a relationship, cannot be computed in Power Query at all, because the model does not exist yet when the query runs. Count how many of the columns are on large tables before deciding, and ignore the finding once the answer is none.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = REDUCE_NUMBER_OF_CALCULATED_COLUMNS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"REDUCE_NUMBER_OF_CALCULATED_COLUMNS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  REDUCE_OBJECTS_WITHIN_VISUALS: {
    fix: "Keep the fields the visual is about and move the rest to where a reader asks for them: secondary measures to a report page tooltip that shows them for the row under the pointer, and detail columns to a drillthrough page. In Power BI Desktop, remove a field by selecting the X beside it in the field well on the Visualizations pane. Where readers do want to choose among many measures or columns, a field parameter (Modeling, then New parameter, then Fields) puts the choice in a slicer, and the visual shows only the fields a reader has picked.",
    ignore:
      'A table or matrix whose job is to show many columns side by side, such as the detail table on a drillthrough page or a table readers export to Excel, is doing what it is for. Six is also a strict budget: Microsoft\'s own guidance recommends limiting a visual to 10 to 20 fields. Check the visual with Performance Analyzer in Power BI Desktop before splitting it, and ignore the finding where it loads quickly and the width is what readers came for.\n\nTo ignore this rule on one visual, add `{ "name": "pbiplint.ignore", "value": "REDUCE_OBJECTS_WITHIN_VISUALS" }` to the `annotations` array of its visual.json. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"REDUCE_OBJECTS_WITHIN_VISUALS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  REDUCE_PAGES: {
    fix: "Start with the pages nobody opens: the usage metrics report in the Power BI service counts views per page, and a page with none in the last month is a candidate for deletion. Pages that show the same visuals for different slices of the data, a region or a year each, can become one page with a slicer, or with bookmarks that switch between views. A report that serves separate audiences can split into one report per audience, each reading the same semantic model. In Power BI Desktop, delete a page by right-clicking its tab and choosing Delete page.",
    ignore:
      'A report whose count is high because of tooltip and drillthrough pages can show readers only a few tabs: those pages count here although readers never see them in the page list. If the visible pages are few and each answers its own question, the count is not a problem. An app-style report that readers move through with buttons rather than tabs is the other case, as long as every page is reachable and in use.\n\nThis rule reports on the report itself, so there is no object to annotate. To turn the rule off for a whole project, set `"REDUCE_PAGES": "off"` under `rules` in `pbiplint.config.json`.',
  },
  REDUCE_TOPN_FILTERS: {
    fix: "Keep Top N where the ranking is the point of the visual and take it off where it is not. In Power BI Desktop, select the visual, find its card under Filters on this visual in the Filters pane, and remove it with the X on the card, or set its Filter type back to Basic filtering. A visual that only needs its largest items first can sort by the measure instead (More options on the visual, then Sort axis) and let the reader scroll. Two Top N filters on the same field, as in the example, rank the same items twice; where they rank by the same measure, keep the one on the visual whose point is the ranking, and let the other sort by the measure.",
    ignore:
      'A Top N filter that caps a table which would otherwise list every row of a large table saves more than it costs: Microsoft\'s optimization guide recommends exactly that, so that a reader who wants a few dozen rows does not load millions. On an Import model with a few hundred items the ranking is cheap as well. Check the page with Performance Analyzer in Power BI Desktop, and ignore the finding when the ranked visuals come back quickly.\n\nTo ignore this rule on one page, add `{ "name": "pbiplint.ignore", "value": "REDUCE_TOPN_FILTERS" }` to the `annotations` array of its page.json. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"REDUCE_TOPN_FILTERS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  REDUCE_USAGE_OF_CALCULATED_COLUMNS_THAT_USE_THE_RELATED_FUNCTION: {
    fix: "Most of the time the column does not need to exist. The value is already on the dimension and the relationship already reaches it, so build the visual on the dimension's column and delete the copy: right-click it in Power BI Desktop's Data pane and choose Delete from model, or remove its `column Name = expression` block from the table's TMDL file, which is what the example above does. Where the value genuinely has to sit on the fact table, because a measure filters by it at row grain or a composite key needs it, bring it in where the rows are loaded rather than after: in Transform data use Merge Queries against the dimension query and expand the one column you want, or add the join to the view the query reads, and the column arrives compressed like any other loaded column. Where the value is only wanted inside one measure, call RELATED there instead, since a measure computes at query time and stores nothing.",
    ignore:
      'A small table is the clean exception. The cost is per row, so RELATED on a dimension of a few thousand rows is not worth an edit, while the same expression on a fact table of fifty million is the reason the model is large. A column that cannot be merged upstream is the other case: where the fact table and the dimension come from different sources and the merge would break query folding, doing the lookup in DAX after load can be the cheaper of the two. Check the row count and check whether the merge folds before rewriting anything. What is not a legitimate exception is a copy of a dimension attribute on a large fact table that exists because the field list was easier to browse that way.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = REDUCE_USAGE_OF_CALCULATED_COLUMNS_THAT_USE_THE_RELATED_FUNCTION` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"REDUCE_USAGE_OF_CALCULATED_COLUMNS_THAT_USE_THE_RELATED_FUNCTION": "off"` under `rules` in `pbiplint.config.json`.',
  },
  REDUCE_USAGE_OF_CALCULATED_TABLES: {
    fix: "Load the table instead of computing it. In Power BI Desktop, choose Transform data and build the query there, or better, point it at a view in the source so every model that needs the table gets the same one; then right-click the calculated table in the Data pane and choose Delete from model. In the TMDL file the difference is in the partition's declaration: `partition Name = calculated` with a DAX expression becomes `partition Name = m` with a Power Query expression, and that declaration is the only thing the rule reads. Where the calculated table came from Auto date/time rather than from you, the way to remove it is to clear that option under Options, Current file, Data Load, not to delete the table. Where a calculated table stays, keep it small and put the reason in the table's description, which is the Description box in the Properties pane.",
    ignore:
      'Several of these tables are features rather than choices. A field parameter and a what-if parameter are both calculated tables that Power BI Desktop writes for you when you use New parameter, and deleting either one breaks the report that uses it. A disconnected table of thresholds or scenario labels, small and static, is in the same position: there is nothing upstream to load it from and nothing to gain by inventing one. A bridge table built with DISTINCT over two fact tables is the judgment call worth making deliberately, because building it in the source is usually better but is not always worth the round trip through another team. What is not a legitimate exception is a large table built with DAX because the source was inconvenient, which is the case the rule is for, and the hidden tables Auto date/time generates, which should be turned off rather than ignored.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = REDUCE_USAGE_OF_CALCULATED_TABLES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"REDUCE_USAGE_OF_CALCULATED_TABLES": "off"` under `rules` in `pbiplint.config.json`.',
  },
  "REDUCE_USAGE_OF_LONG-LENGTH_COLUMNS_WITH_HIGH_CARDINALITY": {
    fix: "Find the columns first. In Power BI Desktop's DAX query view, run a query such as `EVALUATE ROW(\"long rows\", COUNTROWS(FILTER('Sales', LEN('Sales'[Comment]) > 100)), \"distinct\", DISTINCTCOUNT('Sales'[Comment]))` against each text column you suspect. Then deal with the ones that come back large. The cheapest answer is not to load the column: choose Transform data, select the query, and use Choose Columns or Remove Columns, or drop it from the select list of the view the query reads. Where a report does show the text, shorten it where it is loaded, with Extract, First Characters under the Transform tab, or keep the full text in a separate detail table that a drillthrough page reads, so the wide column is never scanned by a summary visual. Where the text is a code or a URL with a repeating prefix, splitting the prefix into its own column gives the dictionary something to compress. DAX Studio's VertiPaq Analyzer reports every column's size and cardinality at once if you would rather start from a list than a query per column, and if you already use Tabular Editor, the walkthrough under Links loads the same statistics into its Best Practice Analyzer, which can then run this rule directly.",
  },
  REDUCE_VISUALS_ON_PAGE: {
    fix: "Decide what the page is for and move the rest somewhere a reader goes on purpose. Detail about one item belongs on a drillthrough page, and context for a single data point on a report page tooltip; neither runs a query until a reader asks for it. Cards that each show one measure can become one card visual that shows them all: in Power BI Desktop, drag the other measures into the first card's Values well in the Visualizations pane and delete the cards they came from. Delete visuals that repeat what another visual on the page already shows.",
    ignore:
      'A page of light visuals can carry more than the default without keeping anyone waiting: on an Import model, a grid of cards that each read one measure can open faster than a page with four large matrices. Open the page with Performance Analyzer in Power BI Desktop (on the Optimize ribbon, then Start recording and Refresh visuals). If every visual comes back quickly and readers still find what the page is about, the count is not the problem on that page.\n\nTo ignore this rule on one page, add `{ "name": "pbiplint.ignore", "value": "REDUCE_VISUALS_ON_PAGE" }` to the `annotations` array of its page.json. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"REDUCE_VISUALS_ON_PAGE": "off"` under `rules` in `pbiplint.config.json`.',
  },
  RELATIONSHIP_COLUMNS_SAME_DATA_TYPE: {
    fix: "Set the two columns to the same type, and prefer a whole number for a key. In Power BI Desktop there are two places to do it: Column tools, Data type on the selected column, which changes the type on the model, or Transform data, where a Changed Type step in Power Query gets the type right before the data is loaded and keeps it right on every refresh. Power Query is the better of the two when the source is the reason the types differ. In the TMDL file the property is `dataType` on each column. Converting a text key to a whole number fails at refresh on any value that is not a number, so look for padded keys such as `007` first and strip the padding in the same Power Query step.",
    ignore:
      'There is nothing to ignore: where both columns name a type and the types differ, set them to the same type. The rule compares only the types the TMDL names, so a relationship with a calculated column saved with no `dataType` line is not reported at all (see Quirks).\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = RELATIONSHIP_COLUMNS_SAME_DATA_TYPE` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"RELATIONSHIP_COLUMNS_SAME_DATA_TYPE": "off"` under `rules` in `pbiplint.config.json`.',
  },
  RELATIONSHIP_COLUMNS_SHOULD_BE_OF_INTEGER_DATA_TYPE: {
    fix: "The type has to change on both ends, so the fix belongs upstream of the model. Where the source already has an integer surrogate key, load it instead of the natural key: in Power BI Desktop, choose Transform data, add the key column to the query, and drop the text one. Where there is no integer key, add one in the source view or build it with a merge in Power Query against the dimension. The Data type box under Column tools changes a column's type in place on an import model, which is worth using only when the values are already digits held as text. Change both ends in the same edit, because a relationship whose two columns end up with different types is a finding of its own.",
    ignore:
      'A date relationship on a DateTime column is the common one to leave: it is what Power BI Desktop builds when you connect a fact table to a date table, it works, and moving the model to an integer date key such as 20260904 is a project rather than a fix. A small dimension is the second: a few thousand rows keyed on a short text code cost almost nothing, and a surrogate key adds a column to build and maintain for a saving nobody will measure. The finding earns its keep on the fact tables, where the key column is one of the widest things in the model.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = RELATIONSHIP_COLUMNS_SHOULD_BE_OF_INTEGER_DATA_TYPE` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"RELATIONSHIP_COLUMNS_SHOULD_BE_OF_INTEGER_DATA_TYPE": "off"` under `rules` in `pbiplint.config.json`.',
  },
  "REMOVE_AUTO-DATE_TABLE": {
    fix: "In Power BI Desktop, open File, Options and settings, Options, then Current file, Data Load, and clear Auto date/time. Desktop deletes the hidden tables and the variations that point at them when the file is saved, so the `table LocalDateTable_...` blocks leave the project's TMDL files on the next save. The option itself is recorded on the model as `annotation __PBI_TimeIntelligenceEnabled`, which Desktop writes and clears for you rather than a property to edit by hand, and deleting the table blocks yourself without clearing the option only invites Desktop to write them again. Then give the model a calendar of its own: add a date table, relate each fact table's date column to it, and mark it with Mark as date table under Table tools, which writes `dataCategory: Time` on the table and `isKey` on its date column. Report authors lose the automatic date hierarchy under each date column when the option goes off, so expect to rebuild the visuals that used one against the new table's Year, Quarter, and Month columns.",
    ignore:
      'There is no lasting exception. These tables are not something a modeler chose, they are what Power BI Desktop falls back to, and every one of them is replaced by the single calendar the model should have anyway. The one honest reason to leave a finding for now is sequencing: in a report with many visuals built on the automatic date hierarchies, clearing the option breaks all of them at once, so the calendar goes in first, the visuals move across, and the option goes off last. That is a plan with a date on it rather than a decision to ignore the rule.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = REMOVE_AUTO-DATE_TABLE` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"REMOVE_AUTO-DATE_TABLE": "off"` under `rules` in `pbiplint.config.json`.',
  },
  REMOVE_DATA_SOURCES_NOT_REFERENCED_BY_ANY_PARTITIONS: {
    fix: "Delete the data source. In the project it is a `dataSource` block, usually in a file of its own under the `dataSources` folder: remove the file and the matching `ref` line in `model.tmdl`, or delete the block where it sits. Power BI Desktop does not show data sources, and Transform data, Data source settings lists the sources the queries name rather than these declarations, so the file is the place to do it. If the source is still wanted, point a partition at it instead, with `dataSource:` under the partition's `source` block.",
    ignore:
      'A model whose partitions are created after it is deployed, by a pipeline or a script that binds them to a source the files do not yet name, keeps the declaration on purpose, and the finding on it is noise. So is a source you have just added and are about to wire up. Outside those, a data source nothing reads is a leftover, and the credential prompt it produces on every deployment is the cost of keeping it.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = REMOVE_DATA_SOURCES_NOT_REFERENCED_BY_ANY_PARTITIONS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"REMOVE_DATA_SOURCES_NOT_REFERENCED_BY_ANY_PARTITIONS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  REMOVE_REDUNDANT_COLUMNS_IN_RELATED_TABLES: {
    fix: "Stop loading the column on the fact table. In Power BI Desktop choose Transform data, select the fact table's query, and use Choose Columns or Remove Columns so the column never reaches the model; where the query reads a view or a stored procedure, drop it from the select list there instead and the refresh gets shorter too. A duplicate that is a DAX calculated column goes instead by right-clicking it in the Data pane and choosing Delete from model, or by removing its `column Name = expression` block from the table's TMDL file. Then point the visuals that used it at the dimension's column, which filters the way a report author expects, and where a measure needs the value at row grain, reach it with RELATED inside the measure rather than storing it again. Hiding the column is not a fix here: the rule never reads a column's visibility, so a hidden copy is reported exactly as a visible one is, and it still costs the same memory.",
    ignore:
      "Coincidence is the common false alarm. The test is the column's name and nothing else, so `'Sales'[Description]` and `'Product'[Description]` are reported as duplicates when one is a line note and the other a catalogue blurb. Read both columns before removing either. A copy kept on purpose is the other legitimate case: a fact table that carries a snapshot of the attribute as it was on the order date is not the dimension's current value and must not be replaced by it, and a column the source system denormalized for a composite key can be cheaper to keep than to rebuild. Check whether the two columns hold the same values for the same key, which a quick visual of both will answer, and ignore the finding where they do not. A plain copy of a slowly changing dimension's current name on a large fact table is what the rule is for.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = REMOVE_REDUNDANT_COLUMNS_IN_RELATED_TABLES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"REMOVE_REDUNDANT_COLUMNS_IN_RELATED_TABLES\": \"off\"` under `rules` in `pbiplint.config.json`.",
  },
  REMOVE_ROLES_WITH_NO_MEMBERS: {
    fix: "Assign the members where the model keeps them. For a semantic model published to the Power BI service, the roles are written in Power BI Desktop under Modeling, Manage roles, and the people are added after publishing: open the workspace, choose Security on the semantic model, pick the role, and add the users or the security groups. For a model whose membership lives in the files, add a `member` block under the role in its TMDL file, with the member's name on the declaration line and `memberType` and `identityProvider` beneath it. If the role is not used at all, delete it, in Desktop under Manage roles or by removing its file from the `roles` folder and its `ref role` line from `model.tmdl`.",
    ignore:
      'On a Power BI semantic model, role membership is held in the service and is never written into the project files, so every role in the project is reported and every one of those findings is noise. The rule earns its place on a model whose roles carry their own members: an Analysis Services model, or one a deployment pipeline writes membership into.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = REMOVE_ROLES_WITH_NO_MEMBERS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"REMOVE_ROLES_WITH_NO_MEMBERS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  REMOVE_UNUSED_CUSTOM_VISUALS: {
    fix: "In Power BI Desktop, right-click the visual's icon among the imported visuals in the Visualizations pane and remove it, confirming when Desktop asks. If a page needs the visual again later, import it again from AppSource.",
    ignore:
      'A report kept as a starting point for other reports, which registers the visuals its authors are expected to use before any page uses them, is the one case where an unused registration is deliberate. A report that readers open is not that case: if a page is about to need the visual, importing it again when that page is built costs a minute.\n\nThis rule reports on the report itself, so there is no object to annotate. To turn the rule off for a whole project, set `"REMOVE_UNUSED_CUSTOM_VISUALS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  REPORT_LEVEL_MEASURES: {
    fix: "Move the measure into the model with the same name, on the same table, with the same DAX, then point the report at it. How depends on how the report reads its model.\n\n**If the project opens its model by path,** as the sample does, the fix edits one report file, which only `PARSE_ISSUE`'s page also asks for among the report pages. Power BI Desktop shows the report measures in such a project, but its menu fails on them, so it cannot rename or remove them (checked in Power BI Desktop 2.158, September 2026).\n\n1. Note each report measure's DAX and any format it sets. A report measure that another one uses moves with it: in the sample, Margin % (report) uses Net Margin.\n2. With Power BI Desktop closed, delete their entries from reportExtensions.json, and an entity when it holds no measure any more. When no measure is left, delete the file itself: Desktop does not open a project whose reportExtensions.json has an empty `entities` list (checked in Power BI Desktop 2.158, September 2026).\n3. Open the project in Power BI Desktop and create each measure with New measure on its table, with the same name and DAX: right-click the table in the Data pane, or hover over it and select More options (...), choose New measure, and type the name and the DAX into the formula bar ([Create a measure](https://learn.microsoft.com/power-bi/transform-model/desktop-tutorial-create-measures#create-a-measure)). In such a project the measure is saved in the model's TMDL (checked in Power BI Desktop 2.158, September 2026).\n4. Put the model's measure in each visual, filter, and bookmark that used the report measure, as step 4 of the route below describes. A visual stays broken until the measure is added again, and a sort on the measure follows it back (checked in Power BI Desktop 2.158, September 2026).\n5. Save the project and lint again: `BROKEN_FIELD_REFERENCE` names any reference left.\n\n**If the report connects live to a published model** and you can change the model, in Power BI Desktop:\n\n1. Open the report so that it connects live to the published model, through the .pbir file When to ignore it describes. Note the measure's DAX and any format it sets, then rename it so the model's measure can take its name: right-click it in the Data pane and select Rename. Checked in Power BI Desktop (version 2.158, September 2026), a report measure's menu in a report connected live to a published model has Rename and Delete from model. Microsoft's schema for report measures asks that a report measure's name be unique across the model, so the two should not exist side by side under one name.\n2. Open the model itself in Power BI Desktop, from its own project or file: in a report that connects live to a model, \"left navigation and modeling are disabled\" ([Connect to semantic models in Power BI](https://learn.microsoft.com/power-bi/connect-data/desktop-report-lifecycle-datasets#considerations-and-limitations)). Right-click the table in the Data pane, or hover over it and select More options (...), choose New measure, and type the name and the DAX into the formula bar. Microsoft notes that this \"saves your new measure in the Sales table\" for its example ([Create a measure](https://learn.microsoft.com/power-bi/transform-model/desktop-tutorial-create-measures#create-a-measure)), so a measure created from a table's menu is saved in that table.\n3. Publish the model. Republishing replaces the semantic model in the service ([Republish or replace a semantic model](https://learn.microsoft.com/power-bi/create-reports/desktop-upload-desktop-files#republish-or-replace-a-semantic-model-published-from-power-bi-desktop)), and \"any changes to the semantic model reflect in the report\" ([Connect to semantic models in Power BI](https://learn.microsoft.com/power-bi/connect-data/desktop-report-lifecycle-datasets#considerations-and-limitations)).\n4. Back in the report, put the model's measure wherever the report measure was: drag it from the Data pane into each well in place of the renamed one ([Create your first visualizations](https://learn.microsoft.com/power-bi/fundamentals/desktop-getting-started#create-your-first-visualizations)), into the Filters pane in place of each filter on it ([Add a filter to a report](https://learn.microsoft.com/power-bi/create-reports/power-bi-report-add-filter#filter-with-a-field-thats-not-in-the-visual)), and, for a visual sorted by it, choose it under More options (...), then Sort axis ([Change the visualization type](https://learn.microsoft.com/power-bi/visuals/power-bi-report-add-visualizations-i#change-the-visualization-type)). For each bookmark that captured it, select More options (...) next to the bookmark's name and choose Update ([Create report bookmarks](https://learn.microsoft.com/power-bi/create-reports/desktop-bookmarks#create-report-bookmarks)).\n5. Delete the renamed report measure: right-click it in the Data pane and select Delete from model, the item step 1's check found on the same menu.\n\nLint again when you are done. A well, filter, sort, or bookmark that still names the report measure after step 5 is reported by `BROKEN_FIELD_REFERENCE`.\n\n**If you cannot change the model,** keep the report measure: it is the supported route for an author who cannot change the model, as When to ignore it says.",
    ignore:
      'A report measure is the supported route for an author who cannot change the model, and such a report can still reach pbiplint beside the model. When the model and the report share a workspace, Fabric Git integration always exports the report with a reference by path to the model. Microsoft describes keeping a second .pbir file that connects to the published model, so that the report opens in live connect to work with report-level measures, while definition.pbir, the file pbiplint reads, keeps its reference by path. If that is how the report is built and the model belongs to someone else, ignore the finding. When the model is yours to change, a measure rarely has a reason to stay in one report.\n\nThis rule reports on measures defined in the report, and pbiplint reads no annotation on them, so there is no object to annotate. To turn the rule off for a whole project, set `"REPORT_LEVEL_MEASURES": "off"` under `rules` in `pbiplint.config.json`.',
  },
  SET_ISAVAILABLEINMDX_TO_TRUE_ON_NECESSARY_COLUMNS: {
    fix: "Power BI Desktop has no setting for this property and never writes it, so the repair is in the TMDL file: delete the `isAvailableInMdx: false` line from under the column and the property goes back to its default of true. The other way to clear the same finding is to remove the need for the attribute hierarchy: take the column out of the hierarchy in Desktop's model view, or clear Sort by column under Column tools on the column that names it, and the rule stops reporting it. For a column a calendar names, take it out of the calendar. In the TMDL file, delete an associated or time-related column's line under its `calendarColumnGroup`. A primary column's line cannot go on its own, because \"The primary column is required for each category\" ([Primary versus associated columns](https://learn.microsoft.com/power-bi/transform-model/desktop-time-intelligence#primary-versus-associated-columns)): remove its whole `calendarColumnGroup`, or name another column as the group's `primaryColumn`. Calendar options in Table tools, which Desktop shows only once the Enhanced DAX Time Intelligence preview is turned on ([Enable the enhanced DAX Time Intelligence preview](https://learn.microsoft.com/power-bi/transform-model/desktop-time-intelligence#enable-the-enhanced-dax-time-intelligence-preview)), makes the same changes for primary and associated columns, but not for a time-related column: Microsoft says tagging one \"isn't currently possible in the calendar options, but can instead only be done using external tools or TMDL\" ([Available column categories](https://learn.microsoft.com/power-bi/transform-model/desktop-time-intelligence#available-column-categories)). Tabular Editor shows the property in its property grid, which is a quicker way to clear it across the batch of columns a single bulk edit set.",
    ignore:
      'There is no case for leaving it. A column reported here is one the engine needs an attribute hierarchy for, and the memory the property saves on it is small next to a model that fails to process. What is worth working out is why the property is there at all: it is almost always one bulk edit made across every hidden column, and the columns that needed the attribute hierarchy are the ones this rule lists. Clear those and leave the rest alone, so the saving stays where it does no harm.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = SET_ISAVAILABLEINMDX_TO_TRUE_ON_NECESSARY_COLUMNS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"SET_ISAVAILABLEINMDX_TO_TRUE_ON_NECESSARY_COLUMNS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  SLICER_SEARCH_SAVED: {
    fix: "In Power BI Desktop, select the slicer, delete the text in its search box, and save the report. Checked in Power BI Desktop, the box then stays empty when the report is reopened. The slicer's eraser also clears the search box; then save the report. The eraser clears the slicer's selection as well, so to keep a selection the report is meant to open with, delete the term instead. Reset to default in the service returns a reader to the report as it was published, saved term included, so the fix belongs in the saved report.",
    ignore:
      'A report meant to open with a long list already narrowed to a starting term, where that is a deliberate choice and whoever opens it knows the list is narrowed. Otherwise there is rarely a reason to keep a saved term.\n\nTo ignore this rule on one visual, add `{ "name": "pbiplint.ignore", "value": "SLICER_SEARCH_SAVED" }` to the `annotations` array of its visual.json. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"SLICER_SEARCH_SAVED": "off"` under `rules` in `pbiplint.config.json`.',
  },
  SLICER_SELECTION_SAVED: {
    fix: "In Power BI Desktop, clear the slicer and save the report in that state, as Microsoft recommends before publishing: select the slicer's Clear button, an eraser icon, then save. On the original slicer the Clear button sits in the Slicer header and shows when you hover over it; on the Slicer (new) visuals it sits in the Visual container header. Either way, if the header that holds it is turned off, turn that header on first, as Microsoft advises for the Slicer header, since the Clear button is not there without it. Check any bookmark that captures the slicer as well, since a bookmark saves slicer state of its own.\n\nA custom slicer from AppSource that filters through the Visual Filters API sets and clears that filter itself, as Microsoft's guidance for building Power BI visuals describes, so the controls for clearing it are the visual's own. In Power BI Desktop, clear it on the visual the way it offers, then save the report in that state. The Chiclet Slicer, for one, is cleared with the Clear button in the visual's top right corner, by its README in Microsoft's repository for the visual. Check any bookmark that captures it as well, since Microsoft's guidance for building visuals says that when a reader switches bookmarks, Power BI hands the visual the filter the bookmark holds.",
    ignore:
      'A default selection readers are meant to start from, which Microsoft endorses for slicers other than range slicers: "you might intentionally save a default selection so that report consumers start with a specific set of filters." Examples are a button slicer or list slicer with Force selection on, or an original slicer with Single select on, which Microsoft\'s visual capability data describes the same way: only one item can be chosen, and the first available is chosen when none is. Others are a slicer saved on the scenario a page opens in, such as Actual rather than Budget, and a field parameter slicer saved on the field the visuals should open with. Microsoft recommends saving range slicers cleared, and says date range slicers typically work best when they start that way, so a saved range deserves a second look. Without a policy the finding is info, a prompt to check each selection; with `expect` set to `none`, ignore it on the slicers whose default is deliberate.\n\nTo ignore this rule on one visual, add `{ "name": "pbiplint.ignore", "value": "SLICER_SELECTION_SAVED" }` to the `annotations` array of its visual.json. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"SLICER_SELECTION_SAVED": "off"` under `rules` in `pbiplint.config.json`.',
  },
  SNOWFLAKE_SCHEMA_ARCHITECTURE: {
    fix: "Fold the sub-dimension into its parent so the parent carries the attributes directly. The best place is the source: have the view the Product query reads join Category and return Category Name as a column, and the refresh does the join once with indexes. Failing that, do it in Power BI Desktop: choose Transform data, select the Product query, use Merge Queries against the Category query on the key, expand the columns you want, then right-click the Category query and choose Delete, which removes the table and the relationship with it. Where the sub-dimension's query has to stay for another reason, delete only the relationship, which is the right-click menu on its line in the model view; in the TMDL file the same change is the sub-dimension's `table` block and its `relationship` block both going, and the parent gaining a plain column. Keep the sub-dimension where the chain has a reason to exist, which the next section describes, and where you do, prefer a single-direction relationship along it.",
    ignore:
      'Several shapes are reported that are not snowflakes at all. A bridge table sits between two dimensions by design, so it is the from side of one relationship and the to side of another and always will be. A sub-dimension shared by several parents, such as one Geography table that both Customer and Store point at, costs less as its own table than as a copy inside each parent. A very large sub-dimension is the third case: folding a million-row attribute table into its parent widens every row of the parent, and the two hops are cheaper than that. A chain of fact tables, such as a line table related to an order header that is itself related to Customer, reports the header for the same structural reason and is a perfectly ordinary design. What is worth acting on is a small lookup table that exists only because the source normalized it and nobody merged it back, which is most of what this rule finds.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = SNOWFLAKE_SCHEMA_ARCHITECTURE` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"SNOWFLAKE_SCHEMA_ARCHITECTURE": "off"` under `rules` in `pbiplint.config.json`.',
  },
  SPECIAL_CHARS_IN_OBJECT_NAMES: {
    fix: "In Power BI Desktop, double-click the field in the Data pane and retype the whole name, a space where the tab is, rather than trying to select the character. In the TMDL file the name is on the declaration line between single quotes: replace the tab with a space so the line reads `column 'Order ID'`, and turn on your editor's whitespace display to see where the tab was. Renaming in Desktop updates the visuals bound to the field; a hand edit in the TMDL file does not, so open the report and check its visuals after one. Where the character arrives with a source column name, rename the column in Power Query as well, so the next column you add from that query comes in clean.",
    ignore:
      'There is no case for it. A tab or a line break in a name buys nothing an ordinary space does not, and it costs every reference to the object an exact match on a character nobody can see.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = SPECIAL_CHARS_IN_OBJECT_NAMES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"SPECIAL_CHARS_IN_OBJECT_NAMES": "off"` under `rules` in `pbiplint.config.json`.',
  },
  SPLIT_DATE_AND_TIME: {
    fix: "Find the columns first. In Power BI Desktop's DAX query view, run a query such as `EVALUATE ROW(\"with a time\", COUNTROWS(FILTER('Sales', HOUR('Sales'[Order Timestamp]) + MINUTE('Sales'[Order Timestamp]) + SECOND('Sales'[Order Timestamp]) > 0)))` against each DateTime column you suspect. Then split the ones that come back. The fix lives where the column is loaded, not in a model property: in Transform data, select the column, use Add Column, Date, Date Only and Add Column, Time, Time Only, then remove the original column, or return the two columns from the view the query reads so the split folds into the refresh. Where nobody asks a question by hour, there is no need for a second column at all: select the column and use Transform, Date, Date Only, which drops the time part in place and collapses the cardinality in one step. Finish by relating the date column to the date table, and the time column to a time table of one row per minute or per hour if the reports need it.",
  },
  TAB_ORDER_FOLLOWS_LAYOUT: {
    fix: "In Power BI Desktop, select the View tab in the ribbon, and under Show panes, select Selection. In the Selection pane, select Tab order to see the page's current tab order. Select an object and use the up and down arrow buttons to move it, or drag it to its place in the list. Select the number next to a decorative object, such as a background shape or an image, to hide it from the tab order, as Microsoft advises for decorative shapes and images.\n\nMeagan Longoria describes a button in the Tab order view, Have tab order match visual order, that reorders the whole page at once, sorting the visuals by their Y and then their X coordinates. By her account of it, the order it writes is one this rule accepts.",
    ignore:
      'The rule reports nothing until the project sets the policy, so a team that does not hold its reports to a tab order leaves the policy unset rather than ignoring findings page by page. Under the policy, the case to judge is a page laid out to be read in columns, such as a column of slicers down the left side that readers should work through before the charts beside it: rows cut across the columns, so the rule reads the top chart before the lower slicers. Grouping the column, by selecting its visuals and choosing Group on the Format menu, lets the rule read it as one place in the order, with its slicers ordered among themselves; put the group where it belongs in the Tab order list, and the finding usually clears without ignoring it. An order that departs from the layout on purpose, such as buttons along the top that readers should reach after the page\'s content, is a choice the rule cannot see; ignore the finding on that page.\n\nTo ignore this rule on one page, add `{ "name": "pbiplint.ignore", "value": "TAB_ORDER_FOLLOWS_LAYOUT" }` to the `annotations` array of its page.json. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"TAB_ORDER_FOLLOWS_LAYOUT": "off"` under `rules` in `pbiplint.config.json`.',
  },
  TRIM_OBJECT_NAMES: {
    fix: "In Power BI Desktop, double-click the field in the Data pane and retype the name without the space, or select the object and clear the space from Name in the Properties pane. In the TMDL file the name is on the declaration line, so `column 'Order ID '` becomes `column 'Order ID'`. A data column carries its own `sourceColumn`, so the model name and the source column name are independent and trimming the model name does not change what the refresh loads. Renaming in Desktop updates the visuals bound to the field; a hand edit in the TMDL file does not, so open the report and check its visuals after one. Where the space arrives with a source column name, trim it in Power Query as well, so the next column you add from that query comes in clean.",
    ignore:
      'No name should start or end with a space. A leading space is sometimes used to push a measure to the top of the field list; a display folder gathers the measure with the ones it belongs beside, and it does that without hiding a character in the name.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = TRIM_OBJECT_NAMES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"TRIM_OBJECT_NAMES": "off"` under `rules` in `pbiplint.config.json`.',
  },
  UDF_NOT_CALLED: {
    fix: "Delete the function, after checking the callers pbiplint cannot see, listed under When to ignore it.\n\nIn Power BI Desktop's Model view, select Model at the top of the Data pane to open [Model explorer](https://learn.microsoft.com/power-bi/transform-model/model-explorer#find-model-explorer), right-click the function under Functions, and choose Delete from model ([Using Model explorer](https://learn.microsoft.com/dax/best-practices/dax-user-defined-functions#using-model-explorer)). In TMDL, remove the function's block from `definition/functions.tmdl`: its `///` description lines, its `function` line, and the lines indented under it. For a package, delete each function that carries its `DAXLIB_PackageId` annotation.",
    ignore:
      "When something outside the model's own DAX calls the function:\n\n- A DAX query, such as a test harness that runs a model's test functions from outside it.\n- A report's own measures, which this rule does not read, including a live-connected report's, which can call the functions of the model it connects to ([Considerations and limitations](https://learn.microsoft.com/dax/best-practices/dax-user-defined-functions#considerations-and-limitations)).\n- A visual calculation, which pbiplint does not read.\n\nOr when the function is kept on purpose, such as one written ahead of the measures that will call it.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = UDF_NOT_CALLED` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `\"UDF_NOT_CALLED\": \"off\"` under `rules` in `pbiplint.config.json`.",
  },
  UDF_USE_COMPOUND_NAMES: {
    fix: "Rename the function to a compound name, such as `Local.AddTax` for a function of the model's own, or a prefix for your organization or library.\n\nIn Power BI Desktop's Model view, select Model at the top of the Data pane to open [Model explorer](https://learn.microsoft.com/power-bi/transform-model/model-explorer#find-model-explorer), right-click the function under Functions, choose Rename, and enter the new name; Desktop updates the measures and functions that call it.\n\nIn TMDL, change the name on the function's line in `definition/functions.tmdl`, in single quotes when it holds a dot (`function 'Local.AddTax' =`), and at every call in the files under `definition/`, where it is written without quotes (`Local.AddTax(`). Searching those files for the old name followed by an opening parenthesis finds the calls.",
    ignore:
      'When the name is fixed by something outside the model: a live-connected report\'s own measures, or a DAX query kept elsewhere, calls the function by that name, and renaming it would break them where nothing in the model shows it. Otherwise the finding is not noise, though the risk it guards against lies in future releases rather than in the model today.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = UDF_USE_COMPOUND_NAMES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"UDF_USE_COMPOUND_NAMES": "off"` under `rules` in `pbiplint.config.json`.',
  },
  UDF_WITHOUT_DESCRIPTION: {
    fix: 'Write a sentence or two on what the function returns and what each parameter expects.\n\nIn Power BI Desktop, open the function in DAX query view: in Model view, select Model at the top of the Data pane to open Model explorer, right-click the function under Functions, and choose Quick queries, then Define and evaluate ([Using Model explorer](https://learn.microsoft.com/dax/best-practices/dax-user-defined-functions#using-model-explorer)). Write `///` lines directly above its `FUNCTION` line and select Update model with changes ([Saving to the model](https://learn.microsoft.com/dax/best-practices/dax-user-defined-functions#saving-to-the-model)); the `///` syntax serves "both measure and function descriptions" ([Add measure descriptions](https://learn.microsoft.com/power-bi/transform-model/dax-query-view#add-measure-descriptions)). In TMDL, add the `///` lines directly above the function\'s `function` line in `definition/functions.tmdl`, with no blank line between the last of them and the declaration.\n\nMicrosoft says parameter descriptions are not supported ([Considerations and limitations](https://learn.microsoft.com/dax/best-practices/dax-user-defined-functions#considerations-and-limitations)), so say what the parameters expect in the description itself; `@param` and `@returns` tags are optional.',
    ignore:
      'A function whose name and parameters already say everything, such as `Local.Double(amount)`, gains little from a sentence repeating them. A function nothing calls is better deleted than described.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = UDF_WITHOUT_DESCRIPTION` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"UDF_WITHOUT_DESCRIPTION": "off"` under `rules` in `pbiplint.config.json`.',
  },
  UNNECESSARY_COLUMNS: {
    fix: "For a data column, stop loading it: in Power BI Desktop, Transform data, select the query, and use Choose Columns or Remove Columns, so the column never reaches the model. Where the query reads a view or a stored procedure, drop it from the select list there instead and the refresh gets shorter too. For a calculated column, right-click it in the Data pane and choose Delete from model, or remove its `column` block from the table's TMDL file. If the column turns out to be needed after all, clear Is hidden in the Properties pane, or remove `isHidden` from under the column in the file, and the finding goes with it.",
    ignore:
      'Report usage is the case to check first. A hidden column that a visual, a slicer, or a report-level filter binds to is in use, but this rule reads the model only, as the source rule does, so it reports that column all the same. When the report is in the input, `NOT_REACHED_FROM_REPORT` says which fields that report never reaches; other reports on the same model are still yours to open before you delete anything. A column named as the default column of a variation is in the same position: the rule does not read variations, so it reports one that Power BI Desktop is quietly relying on. A staging column you are about to reference is a fair thing to leave for a week. A hidden key that no relationship uses is not: that one is what the rule is for.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = UNNECESSARY_COLUMNS` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"UNNECESSARY_COLUMNS": "off"` under `rules` in `pbiplint.config.json`.',
  },
  UNNECESSARY_MEASURES: {
    fix: "In Power BI Desktop, right-click the measure in the Data pane and choose Delete from model, or, if reports still use it, clear Is hidden in the Properties pane so the dependency is visible to the next person. In the TMDL file, remove the `measure` block from its table, or remove `isHidden` from under it. Search the project for the measure's name before you delete it: this rule has already searched the model's DAX (measures with their format strings and KPIs, calculated columns and tables, calculation items, row-level security filters, and user-defined functions), so what a search adds is the report files, which this rule does not read, and anything else in the model that names the measure.",
    ignore:
      'Report usage is the case to check first. A hidden measure that a visual or a report-level filter binds to directly is in use, but this rule reads the model only, as the source rule does, so it reports that measure all the same. When the report is in the input, `NOT_REACHED_FROM_REPORT` says which fields that report never reaches; other reports on the same model are still yours to open before you delete a measure. A measure you have written for a calculation item or a measure you have not finished is a fair thing to leave for as long as that lasts. A hidden measure nobody can name a caller for is what the rule is for.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = UNNECESSARY_MEASURES` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"UNNECESSARY_MEASURES": "off"` under `rules` in `pbiplint.config.json`.',
  },
  "UNPIVOT_PIVOTED_(MONTH)_DATA": {
    fix: "Reshape the table where it is loaded. In Power BI Desktop choose Transform data, select the query, select the month columns, and use Unpivot Columns on the Transform tab, or select the columns that are not months and use Unpivot Other Columns so next year's column is picked up without an edit; then rename the Attribute and Value columns to something a report author will recognize, such as Month Name and Amount. Where the source is a warehouse, the same reshape belongs in a view there, and the refresh gets the finished shape for nothing. Back in the model, give the month column a Month Number column to sort by, which is Sort by column on the Column tools tab and `sortByColumn` in the TMDL file. A month name is text and cannot carry a relationship to a day-grain date table, so load the month's start date alongside it, as a Month Start column of the first of each month, and relate that column to the date table; time intelligence then works over the reshaped table. The rule reads the model's columns, so the finding clears as soon as the reshaped query is applied.",
    ignore:
      'A coincidence is the case to check for first, though it takes six of them at once. The month names are matched as substrings of the column names, so Janitorial Cost satisfies Jan, Margin satisfies Mar, Apron Sales satisfies Apr, and Junior Rate satisfies Jun; a table of numeric metrics carrying one such name for each of the six months is reported with no month in it anywhere. Read the column names before reshaping anything. A genuinely pivoted table can also be deliberate: a small budget entry table that a person maintains by hand in a spreadsheet is easier to fill in wide, and where it is a handful of rows, unpivoting it on the way in costs nothing and unpivoting it at the source costs an argument. What is not a legitimate exception is a wide fact table of months feeding visuals through twelve near-identical measures, which is the pattern the rule exists to catch.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = UNPIVOT_PIVOTED_(MONTH)_DATA` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"UNPIVOT_PIVOTED_(MONTH)_DATA": "off"` under `rules` in `pbiplint.config.json`.',
  },
  USE_THE_DIVIDE_FUNCTION_FOR_DIVISION: {
    fix: "Pass the numerator and the denominator as the first two arguments, and add a third where blank is the wrong answer for an empty denominator:\n\n```\nAverage Price = DIVIDE ( SUM ( Sales[Amount] ), SUM ( Sales[Quantity] ) )\n```\n\nIn Power BI Desktop, select the measure in the Data pane and edit it in the formula bar; a calculated column and a calculation item are edited the same way. In the TMDL file, edit the expression after `measure 'Average Price' =`, after `column Name =` for a calculated column, or after `calculationItem Name =` in the calculation group.",
    ignore:
      'A denominator that cannot be zero makes the guard dead weight. Dividing by a literal, `[Total Sales] / 12` for a monthly average, is the clearest case: there is no blank to protect against, and the operator says what it means. The same goes for a denominator the source constrains to be positive, as long as you can point at the constraint rather than at the data you happen to have today. Everywhere else, check what the visual should show when the denominator is empty and put that in DIVIDE\'s third argument.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = USE_THE_DIVIDE_FUNCTION_FOR_DIVISION` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"USE_THE_DIVIDE_FUNCTION_FOR_DIVISION": "off"` under `rules` in `pbiplint.config.json`.',
  },
  USE_THE_TREATAS_FUNCTION_INSTEAD_OF_INTERSECT: {
    fix: "Pass the values you are filtering by first and the column you are filtering second, and drop the VALUES call on the target side:\n\n```\nBudgeted Product Sales = CALCULATE ( [Total Sales], TREATAS ( VALUES ( Budget[Product ID] ), Sales[Product ID] ) )\n```\n\nThe argument order is the reverse of what INTERSECT reads most naturally, so check which side is the filter before you swap the call. In Power BI Desktop, select the measure in the Data pane and edit it in the formula bar; a calculation item is edited the same way from the model view. In the TMDL file, edit the expression after `measure 'Budgeted Product Sales' =`, or after `calculationItem Name =` in the calculation group.",
    ignore:
      'INTERSECT used as set logic rather than as a virtual relationship has no TREATAS equivalent. Counting the products that appear in both Sales and Budget, `COUNTROWS(INTERSECT(VALUES(Sales[Product ID]), VALUES(Budget[Product ID])))`, is asking for the overlap itself, not for a filter, and rewriting it with TREATAS would change what it answers. What to check is whether the result of the call is being counted or read, in which case leave it, or handed to CALCULATE as a filter, in which case the rule is right.\n\nTo ignore this rule on one object, add `annotation pbiplint.ignore = USE_THE_TREATAS_FUNCTION_INSTEAD_OF_INTERSECT` under the object in its TMDL file. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"USE_THE_TREATAS_FUNCTION_INSTEAD_OF_INTERSECT": "off"` under `rules` in `pbiplint.config.json`.',
  },
  VISUAL_OUTSIDE_PAGE: {
    fix: "In Power BI Desktop, select the visual, open the Format pane, select the General tab, and under Properties change its Position, the horizontal and vertical position in pixels from the top-left corner of the canvas, or its Size, the height and width in pixels, until it ends inside the page. For a visual inside a group, select the group and move or resize it the same way. If the page should be larger instead, change its size: with nothing selected on the page, the Visualizations pane shows Format page options, and under Canvas settings you can choose a larger Size, or the Custom type to set the height and width in pixels yourself.",
    ignore:
      'A decorative shape or image sized to run past the edge on purpose, such as a background band meant to reach the page\'s border, loses nothing a reader needs; ignore the finding on it. For a visual that shows data there is no legitimate exception.\n\nTo ignore this rule on one visual, add `{ "name": "pbiplint.ignore", "value": "VISUAL_OUTSIDE_PAGE" }` to the `annotations` array of its visual.json. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"VISUAL_OUTSIDE_PAGE": "off"` under `rules` in `pbiplint.config.json`.',
  },
  VISUAL_WITHOUT_FIELDS: {
    fix: "Decide what the visual was meant to show. In Power BI Desktop, select it and drag those fields from the Data pane into its wells in the Visualizations pane; the wells depend on the visual's type, such as the X-axis area of a column chart, or the Bubble size and Legend areas of a map. If the page does not need the visual, delete it.",
    ignore:
      'A custom visual, or a visual type newer than pbiplint, that takes no fields, such as a custom visual that only draws a logo or a menu, is not a data visual, but pbiplint cannot tell that from the file and counts it as one. Check the Visualizations pane with the visual selected: if it offers no wells to fill, ignore the finding on it.\n\nTo ignore this rule on one visual, add `{ "name": "pbiplint.ignore", "value": "VISUAL_WITHOUT_FIELDS" }` to the `annotations` array of its visual.json. Power BI Desktop keeps the annotation. To turn the rule off for a whole project, set `"VISUAL_WITHOUT_FIELDS": "off"` under `rules` in `pbiplint.config.json`.',
  },
};

/** The judgment list from packages/cli/skill/SKILL.md, as Markdown bullets: what holds for every rule. */
export const JUDGMENT =
  "- Keep the tabs TMDL uses for indentation, and keep the formatting and key order Power BI Desktop writes, so a change shows as a small diff.\n- Leave each report file's `$schema` as it is.\n- Power BI Desktop can overwrite files that change while it has the project open. If the user may have it open, ask before changing files.\n- Never clear a finding by ignoring it, changing the lint configuration, or deleting the object it names, without the user's say-so.\n- When a finding matches its rule's \"When to ignore it\" case, ask the user rather than fixing it.\n- Renaming a table, column, or measure reaches the report's files too. After a rename, check the whole project, not only the model.\n- Info findings are suggestions, not a to-do list.";
